window.BANQUE_INFINI = {"module":"annee-1/theorique/semestre-1/methodes-et-techniques-de-recherche","titre":"MTR I","sources":[{"t":"MTR — Annales — Révision transversale","q":"qcm/annales-transversal.html","f":"accueil-methodes-et-techniques-de-recherche.html"},{"t":"MTR — Fondements de la démarche scientifique","q":"qcm/chapitre-1-fondements.html","f":"fiches/chapitre-1-fondements.html"},{"t":"MTR — Pratique fondée sur les preuves","q":"qcm/chapitre-2-pratique-fondee-preuves.html","f":"fiches/chapitre-2-pratique-fondee-preuves.html"},{"t":"MTR — Projet de recherche","q":"qcm/chapitre-3-projet-recherche.html","f":"fiches/chapitre-3-projet-recherche.html"},{"t":"MTR — Méthodologie","q":"qcm/chapitre-4-methodologie.html","f":"fiches/chapitre-4-methodologie.html"},{"t":"MTR — Chercher la meilleure preuve","q":"qcm/chapitre-5-chercher-preuve.html","f":"fiches/chapitre-5-chercher-preuve.html"},{"t":"MTR — Organisation du travail","q":"qcm/chapitre-6-organisation.html","f":"fiches/chapitre-6-organisation.html"},{"t":"MTR — Rédaction scientifique","q":"qcm/chapitre-7-redaction.html","f":"fiches/chapitre-7-redaction.html"}],"questions":[{"q":"<div class='case'>Une étudiante en kiné veut étudier la prévalence des troubles musculo-squelettiques chez les étudiants de son école.</div>Quel design est le plus adapté ?","o":["RCT","Étude transversale","Cas-témoins","Cohorte prospective"],"r":1,"e":"Mesure à un instant T d'une fréquence dans une population = étude transversale.","s":0},{"q":"<div class='case'>Vous voulez comparer l'efficacité de 2 programmes d'exercices sur la douleur fémoro-patellaire.</div>Quel design vous donne la meilleure preuve causale ?","o":["Une étude de cas, sur un patient","Un essai clinique randomisé contrôlé","Une étude transversale, sur un échantillon","Une série de cas, sans groupe contrôle"],"r":1,"e":"Comparer 2 interventions → RCT (groupe expérimental + contrôle + randomisation = gold standard).","s":0},{"q":"<div class='case'>Vous souhaitez identifier les facteurs de risque de la lombalgie chronique chez les manutentionnaires.</div>Quel design est le plus adapté ?","o":["RCT","Cas-témoins","Étude transversale","Méta-analyse"],"r":1,"e":"Identifier des facteurs de risque rétrospectivement = cas-témoins (OR).","s":0},{"q":"<div class='case'>Vous voulez suivre l'évolution fonctionnelle de patients post-AVC sur 12 mois.</div>Quel design ?","o":["Étude transversale","Cohorte prospective","Cas-témoins","Méta-analyse"],"r":1,"e":"Suivi dans le temps = cohorte (prospective ici).","s":0},{"q":"<div class='case'>Vous voulez comprendre comment les patients atteints de douleur chronique vivent leur prise en charge.</div>Quel paradigme/méthode ?","o":["Le quantitatif, par un essai randomisé","Le qualitatif, par des entretiens semi-dirigés","Le quantitatif, par une étude transversale sur échantillon","Une méta-analyse des essais existants"],"r":1,"e":"Vécu, perceptions → qualitatif (entretiens, focus groups).","s":0},{"q":"<div class='case'>« Chez les adultes lombalgiques chroniques (P), un programme d'aquathérapie de 6 mois (I) améliore-t-il davantage la douleur (O) qu'une kiné conventionnelle (C) ? »</div>Que représente la lettre T (PICOT) implicite ici ?","o":["Le type d'étude, sur 2 groupes","Le temps de suivi, soit les 6 mois","Le traitement, ici l'aquathérapie","Le tableau de mesure, ici l'EVA"],"r":1,"e":"T = Temps. Ici 6 mois = durée d'intervention/suivi.","s":0},{"q":"<div class='case'>Étude diagnostique : sur 200 patients, le test détecte 90 vrais positifs et 10 faux négatifs.</div>La sensibilité du test est :","o":["90 %","50 %","10 %","100 %"],"r":0,"e":"Sensibilité = VP / (VP + FN) = 90 / (90 + 10) = 90 %.","s":0},{"q":"Un test très SENSIBLE :","o":["A peu de faux négatifs","A peu de faux positifs","Détecte tous les vrais négatifs","Est inutile"],"r":0,"e":"Sensible = peu de faux négatifs (détecte les vrais positifs).","s":0},{"q":"Un test très SPÉCIFIQUE :","o":["A peu de faux positifs","A peu de faux négatifs","Détecte tous les vrais positifs","Est synonyme de sensible"],"r":0,"e":"Spécifique = peu de faux positifs (détecte les vrais négatifs).","s":0},{"q":"L'Odds Ratio (OR) est calculé dans :","o":["Les études cas-témoins","Les RCT","Les revues qualitatives","Les transversales seulement"],"r":0,"e":"OR est l'indicateur statistique typique des études cas-témoins (association exposition-maladie).","s":0},{"q":"<div class='case'>Vous lisez un article : 50 patients pour 1 thérapeute, programme appliqué à tous, comparaison avant/après. Pas de groupe contrôle, pas de randomisation.</div>Il s'agit d'une étude :","o":["Un essai randomisé contrôlé","Une étude quasi-expérimentale","Une étude cas-témoins","Une méta-analyse de plusieurs essais"],"r":1,"e":"Intervention + comparaison avant/après mais SANS randomisation = quasi-expérimentale.","s":0},{"q":"Quel est le niveau de preuve LE PLUS BAS de la pyramide ?","o":["La méta-analyse de plusieurs essais","L'essai randomisé contrôlé","L'étude de cohorte prospective","L'avis d'expert ou la série de cas"],"r":3,"e":"Base de la pyramide : opinions d'experts, séries de cas, études transversales.","s":0},{"q":"Quel est le niveau de preuve LE PLUS HAUT ?","o":["Un essai randomisé unique","Les méta-analyses et revues systématiques","Une étude de cohorte prospective de grande taille","Une étude cas-témoins rétrospective"],"r":1,"e":"Sommet : méta-analyses et revues systématiques.","s":0},{"q":"Les 3 piliers de Sackett (EBP) sont :","o":["Preuve, expertise clinique et valeurs du patient","Diagnostic, traitement et suivi du patient","Méthodes, résultats et discussion de chaque article lu","Coût, bénéfice et risque du traitement"],"r":0,"e":"Sackett 2000 : preuve scientifique + expertise clinique + valeurs/préférences du patient. Il s'agit de la preuve scientifique.","s":0},{"q":"Les 5 A de la PBE sont :","o":["Ask, Acquire, Appraise, Apply, Analyze","Adopt, Adapt, Apply, Affirm, Achieve","Assess, Ask, Answer, Apply, Audit","Analyze, Assess, Adopt, Adapt, Apply"],"r":0,"e":"5 A : Ask, Acquire, Appraise, Apply, Analyze.","s":0},{"q":"En méthodo : « est-ce que la mesure reflète bien ce qu'on prétend mesurer ? » concerne :","o":["La validité","La fiabilité","La randomisation","La sensibilité"],"r":0,"e":"Validité = mesurer ce qu'on prétend mesurer.","s":0},{"q":"« Si on refait la mesure, obtient-on le même résultat ? » concerne :","o":["La validité","La fiabilité","L'éthique","Le coût"],"r":1,"e":"Fiabilité = reproductibilité de la mesure.","s":0},{"q":"<div class='case'>Vous voulez tester une nouvelle technique de manipulation cervicale. On randomise 80 patients : groupe A nouvelle technique, groupe B technique standard.</div>Quel type d'étude ?","o":["Une étude de cohorte","Un essai randomisé contrôlé","Une étude cas-témoins rétrospective","Une étude transversale"],"r":1,"e":"Randomisation + intervention + comparaison = RCT.","s":0},{"q":"<div class='case'>Une étude veut savoir : « Quelle est l'incidence de la pneumonie associée à la ventilation chez les patients intubés > 48 h ? »</div>Type de question :","o":["Une question d'intervention","Une question d'étiologie","Une question de fréquence, ou d'incidence","Une question de diagnostic, sur la valeur d'un test"],"r":2,"e":"Mesure d'incidence = question de fréquence.","s":0},{"q":"Dans une revue de littérature, organiser par THÈMES plutôt que par AUTEURS permet :","o":["D'éviter l'effet « liste »","De gagner en pages","De plagier facilement","Aucun intérêt"],"r":0,"e":"Par thèmes (douleur, fonction, adhésion…) = synthèse réelle. Par auteurs = liste indigeste.","s":0},{"q":"Quel critère FINER concerne la faisabilité ?","o":["F","I","N","E"],"r":0,"e":"F = Faisable (ressources, temps, accès).","s":0},{"q":"<div class='case'>Vous écrivez : « Évaluer la diminution de la douleur cervicale après 8 semaines de thérapie manuelle. »</div>Cet objectif est :","o":["Oui, il remplit tous les critères","Non, il n'est pas spécifique","Non, il n'est pas mesurable","Non, il n'est pas défini dans le temps"],"r":0,"e":"Spécifique (douleur cervicale), Mesurable (EVA), Atteignable, Relevant, Temporel (8 sem) = SMART. Il est donc SMART.","s":0},{"q":"En APA 7, pour un article de Dupont, Martin, Robert et Garcia (2022), on cite dans le texte :","o":["(Dupont, Martin, Robert & Garcia, 2022)","(Dupont et al., 2022) dès la 1ʳᵉ citation","(Dupont, 2022)","(Dupont et autres, 2022)"],"r":1,"e":"APA 7 : pour 3+ auteurs, et al. dès la 1ʳᵉ citation.","s":0},{"q":"<div class='case'>Vous citez une étude qui dit : « Les exercices excentriques réduisent significativement la douleur d'Achille à 12 semaines (p < 0,05). »</div>Cette mention est de type :","o":["Paraphrase","Transcription mot à mot","Plagiat","Citation indirecte"],"r":1,"e":"Reprise mot à mot entre guillemets = transcription (citation littérale).","s":0},{"q":"<div class='case'>Vous reformulez : « Selon Smith et al. (2020), les exercices excentriques semblent diminuer la douleur d'Achille. »</div>Cette mention est :","o":["Paraphrase","Citation littérale","Plagiat","Non citée"],"r":0,"e":"Reformulation avec ses propres mots + référence = paraphrase (forme préférée).","s":0},{"q":"Une variable confondante peut :","o":["Fausser la relation entre la cause et l'effet mesuré","Être ignorée sans conséquence sur les résultats","Toujours être neutralisée par la randomisation","Ne jamais exister dans un essai bien conduit"],"r":0,"e":"Confondante = facteur externe (âge, sexe, comorbidités) qui influence la VD. La cause est la VI, l'effet mesuré la VD.","s":0},{"q":"L'hypothèse nulle (H0) :","o":["Est ce que l'on teste statistiquement","Affirme l'existence d'un effet réel","N'existe pas en statistiques","Est toujours rejetée à la fin"],"r":0,"e":"On teste H0 : si les résultats sont improbables sous H0, on la rejette.","s":0},{"q":"<div class='case'>Vous lisez : « Saturation = 95 %, FR = 28/min, EVA = 7/10 ».</div>Ces données sont :","o":["Qualitatives, car elles décrivent le patient","Quantitatives, car ce sont des mesures chiffrées","Inutilisables, car elles mélangent plusieurs unités de mesure","Des hypothèses, à vérifier ensuite"],"r":1,"e":"Mesures chiffrées = données quantitatives.","s":0},{"q":"<div class='case'>Verbatim d'un patient : « J'ai peur de bouger, je crois que la douleur empire si je marche. »</div>Donnée :","o":["Qualitative","Quantitative","Inutilisable","Une variable confondante"],"r":0,"e":"Verbatim = donnée qualitative.","s":0},{"q":"Quels exemples NE sont PAS des preuves scientifiques recevables ? (plusieurs)","o":["« Ça marche sur moi », disent certains","« Je l'ai vu sur Instagram »","Une méta-analyse de la Cochrane","Une recommandation officielle du NICE","« On a toujours fait comme ça »"],"r":[0,1,4],"e":"Témoignage personnel, anecdote sociale et tradition ne sont PAS des preuves.","s":0},{"q":"Pour citer plusieurs auteurs dans la même parenthèse en APA :","o":["Par ordre alphabétique, séparés par un point-virgule","Par ordre chronologique, séparés par une virgule","Par âge des auteurs, du plus jeune au plus âgé","Au hasard, séparés par un tiret"],"r":0,"e":"(Gomes, 2001 ; Lages, 1991 ; Silva, 2010) → ordre alphabétique.","s":0},{"q":"<div class='case'>Vous formulez la question : « La kiné respiratoire améliore-t-elle la saturation chez les enfants atteints de bronchiolite ? »</div>Le O est :","o":["La kiné respiratoire","La bronchiolite","Les enfants","La saturation"],"r":3,"e":"O = Outcome = ce qu'on mesure = saturation.","s":0},{"q":"Quel logiciel de gestion bibliographique permet d'insérer automatiquement les citations dans Word ?","o":["Zotero","TikTok","ChatGPT seul","Aucun"],"r":0,"e":"Zotero, Mendeley, EndNote : tous insèrent les citations et la biblio automatiquement.","s":0},{"q":"En recherche PubMed, pour trouver des synonymes :","o":["AND","OR","NOT","Parenthèses uniquement"],"r":1,"e":"OR sert à élargir et couvrir les synonymes (ex. physiotherapy OR \"physical therapy\").","s":0},{"q":"<div class='case'>Vous voulez exclure les chirurgies de votre recherche.</div>Vous utilisez :","o":["AND surgery","OR surgery","NOT surgery","NEAR surgery"],"r":2,"e":"NOT exclut un terme : ex. \"low back pain\" NOT surgery.","s":0},{"q":"« <code>physiother*</code> » est un exemple de :","o":["Troncature","Booléen","Filtre","Guillemets"],"r":0,"e":"Troncature : trouve physiotherapy, physiotherapeutic, physiotherapist…","s":0},{"q":"Selon le cours, lequel décrit la PIE par rapport à la PBE ?","o":["Plus rigide, appliquant les protocoles tels quels","Plus contextuelle, adaptée au patient","Plus dogmatique, fondée sur la tradition","Indépendante des preuves scientifiques"],"r":1,"e":"PIE = Pratique Informée par l'Évidence = plus souple, adaptable au contexte.","s":0},{"q":"<div class='case'>Un thérapeute applique le protocole exact d'une méta-analyse à un patient âgé arthrosique sans modification.</div>Approche :","o":["PBE stricte","PIE adaptative","Hors EBP","Pratique traditionnelle"],"r":0,"e":"PBE stricte : application du protocole validé tel quel.","s":0},{"q":"<div class='case'>Même cas, mais le thérapeute ajuste les charges et ajoute des exercices isométriques.</div>Approche :","o":["PBE stricte","PIE","Pseudoscience","Sans intérêt"],"r":1,"e":"PIE : adaptation contextualisée tout en respectant les preuves.","s":0},{"q":"Quels éléments sont essentiels dans la section MÉTHODOLOGIE d'un mémoire ? (plusieurs)","o":["Population et critères inclusion/exclusion","Instruments de mesure","Variables (VI, VD, confondantes)","Anecdotes personnelles","Procédures et calendrier"],"r":[0,1,2,4],"e":"Méthodologie : population, instruments, variables, procédures, calendrier, analyse statistique, éthique.","s":0},{"q":"Dans le processus de recherche, la méthodologie correspond à l'étape :","o":["La 3ᵉ, entre la revue de littérature et la collecte","La 1ʳᵉ, avant même la formulation du problème","La 5ᵉ, après l'analyse statistique des données","La 6ᵉ, à la toute fin, avec l'application"],"r":0,"e":"Les six étapes vont de la formulation du problème à l'application des résultats.","s":0},{"q":"Le gold standard de la recherche clinique associe :","o":["Randomisation, groupe traité et groupe contrôle","Un grand échantillon, et un suivi de longue durée","Une méta-analyse de plusieurs essais","Une étude de cohorte prospective"],"r":0,"e":"C'est l'essai clinique randomisé, ou RCT. C'est l'essai clinique randomisé.","s":0},{"q":"Les trois piliers de la pratique fondée sur les preuves selon Sackett sont :","o":["La preuve, l'expertise clinique et les valeurs du patient","La preuve, le protocole et la mesure de tous les résultats","Les étapes ask, acquire et appraise","La science, l'expérience et le contexte social"],"r":0,"e":"L'EBPP selon l'APTA y ajoute le contexte social et environnemental.","s":0},{"q":"Dans la pyramide de l'évidence, le sommet réunit :","o":["Revues systématiques, méta-analyses et guidelines","Les essais randomisés contrôlés, de bonne qualité","Les études de cohorte prospectives","Les opinions d'experts reconnus"],"r":0,"e":"Plus on monte, moins il y a de risque de biais.","s":0},{"q":"Une étude cas-témoins permet de calculer :","o":["Un odds ratio, pour repérer des facteurs de risque","Une prévalence, à un instant donné dans la population","Un risque relatif, par suivi prospectif","Une sensibilité, face à un test"],"r":0,"e":"Elle est rétrospective et compare des cas à des témoins.","s":0},{"q":"La sensibilité d'un test correspond à :","o":["Détecter les vrais positifs et limiter les faux négatifs","Détecter les vrais négatifs et limiter les faux positifs","Donner le même résultat d'une mesure à l'autre","Mesurer bien ce qu'il prétend mesurer"],"r":0,"e":"La spécificité détecte les vrais négatifs et limite les faux positifs.","s":0},{"q":"La validité d'un instrument répond à la question :","o":["Mesure-t-on bien ce que l'on prétend mesurer ?","Obtient-on le même résultat en refaisant la mesure ?","L'outil est-il récent ?","L'outil est-il pratique ?"],"r":0,"e":"La fiabilité s'évalue par le test-retest et l'accord inter-évaluateurs.","s":0},{"q":"L'hypothèse testée en statistiques est :","o":["L'hypothèse nulle","L'hypothèse alternative","Les deux simultanément","Aucune des deux"],"r":0,"e":"Si les résultats sont improbables sous H0, on la rejette, ce qui donne du poids à H1.","s":0},{"q":"L'opérateur booléen qui élargit les résultats est :","o":["OR","AND","NOT","*"],"r":0,"e":"AND réduit par intersection et NOT exclut un terme.","s":0},{"q":"Les termes MeSH constituent :","o":["Un vocabulaire contrôlé, pour indexer les articles","Un opérateur booléen, pour combiner plusieurs mots-clés","Un filtre de date de publication","Une troncature de mots-clés"],"r":0,"e":"Ils évitent les ambiguïtés et regroupent les articles malgré les synonymes. C'est l'indexation de PubMed.","s":0},{"q":"Quels sont les 4 piliers de la science selon le cours ?","o":["Observation, Question, Expérimentation, Analyse","Observation, Croyance, Tradition, Intuition","Lecture, Écriture, Mesure, Hypothèse","Hypothèse, Théorie, Loi, Postulat"],"r":0,"e":"Les 4 piliers : Observation → Question → Expérimentation → Analyse.","s":1},{"q":"Selon Kerlinger, quelles propriétés caractérisent une investigation scientifique ?","o":["Empirique","Systématique","Critique","Contrôlée","Intuitive"],"r":[0,1,2,3],"e":"Kerlinger : empirique (mesurable), systématique (protocole), critique (remise en question), contrôlée (limite les biais).","s":1},{"q":"Que signifie « empirique » dans une démarche scientifique ?","o":["Basé sur l'expérience subjective","Basé sur des données mesurables","Basé sur la tradition","Basé sur l'opinion d'experts"],"r":1,"e":"Empirique = données mesurables (goniométrie, EVA, isocinétique...).","s":1},{"q":"Dans l'étude de l'effet du temps d'étude sur la note à l'examen, le temps d'étude est :","o":["Une variable dépendante","Une variable indépendante","Une variable parasite","Une hypothèse"],"r":1,"e":"La VI est la cause supposée (ici le temps d'étude), manipulée/contrôlée.","s":1},{"q":"Une question sur « le délai de récupération après rupture du LCA » est de type :","o":["Intervention","Diagnostic","Pronostic","Étiologie"],"r":2,"e":"Question sur l'évolution dans le temps = pronostic.","s":1},{"q":"Quel type d'étude est le mieux adapté pour répondre à une question d'INTERVENTION ?","o":["Une étude cas-témoins","Une étude transversale, sur un échantillon","Un essai randomisé, ou sa méta-analyse","Des entretiens qualitatifs"],"r":2,"e":"Les RCT et méta-analyses testent l'efficacité causale d'un traitement.","s":1},{"q":"Quel type d'étude pour une question ÉTIOLOGIQUE (facteurs de risque) ?","o":["Un essai randomisé, pour comparer deux groupes","Une étude cas-témoins, avec un odds ratio","Une étude transversale, à un instant donné","Une méta-analyse des essais publiés"],"r":1,"e":"Les études cas-témoins comparent cas vs témoins et identifient les facteurs de risque (OR).","s":1},{"q":"Que signifie l'acronyme PICO ?","o":["Patient, Intervention, Comparison, Outcome","Pathologie, Indication, Critère, Objectif","Protocole, Investigation, Collecte, Observation","Population, Inférence, Conclusion, Objectif"],"r":0,"e":"PICO = Patient (Population) · Intervention · Comparison · Outcome. PICOT ajoute le Temps.","s":1},{"q":"La sensibilité d'un test diagnostique est :","o":["La capacité à détecter les vrais positifs","La capacité à détecter les vrais négatifs","La probabilité d'un faux positif","Le rapport entre VP et FP"],"r":0,"e":"Sensibilité = vrais positifs (test sensible = peu de faux négatifs). Spécificité = vrais négatifs.","s":1},{"q":"Un test très spécifique se caractérise par :","o":["Beaucoup de faux positifs","Peu de faux positifs","Beaucoup de faux négatifs","Une bonne reproductibilité uniquement"],"r":1,"e":"Test spécifique = peu de faux positifs (détecte bien les vrais négatifs).","s":1},{"q":"Une question qualitative est de la forme :","o":["L'aquathérapie réduit-elle la douleur ?","Quelle est la prévalence de la lombalgie ?","Comment les patients vivent-ils leur douleur ?","Quel est le risque lié au tabac pour la lombalgie chronique ?"],"r":2,"e":"La recherche qualitative explore le vécu, les perceptions, les émotions.","s":1},{"q":"Quelles affirmations sur l'EBP sont vraies ? (plusieurs)","o":["Elle combine preuves, expertise et valeurs","Elle exclut l'avis du patient de la décision finale","Elle s'oppose à la seule pratique fondée sur la tradition","Elle est synonyme de tradition clinique bien établie"],"r":[0,2],"e":"L'EBP combine 3 piliers : preuve scientifique + expertise clinique + valeurs du patient. Les valeurs sont celles du patient.","s":1},{"q":"Quel test pour répondre à : « Le test de Lachman est-il plus sensible que le pivot-shift ? »","o":["Un essai randomisé, sur deux groupes","Une étude diagnostique, sur sensibilité et spécificité","Une étude de cohorte, suivie sur plusieurs années de recul","Une étude cas-témoins, rétrospective"],"r":1,"e":"Question diagnostique → étude évaluant la sensibilité/spécificité d'un test.","s":1},{"q":"Quel est l'ordre des étapes du raisonnement hypothético-déductif ?","o":["Observation, question, hypothèse, prédiction, test, conclusion","Question, observation, test, hypothèse, puis conclusion","Hypothèse, observation, question, puis conclusion","Test, hypothèse, observation, question, prédiction et conclusion"],"r":0,"e":"Observation → Question → Hypothèse → Prédiction → Test → Données → Conclusion.","s":1},{"q":"Une étude « cas-témoins » est :","o":["Prospective et expérimentale","Rétrospective et observationnelle","Toujours randomisée","Une revue systématique"],"r":1,"e":"Cas-témoins = observationnelle, rétrospective. Utile pour maladies rares et hypothèses préliminaires.","s":1},{"q":"Que mesure l'« Odds Ratio » dans les études cas-témoins ?","o":["L'efficacité d'un traitement","Une association entre exposition et maladie","Le délai moyen de récupération après la lésion","La validité diagnostique d'un test"],"r":1,"e":"L'OR quantifie l'association exposition-maladie dans les cas-témoins.","s":1},{"q":"Quelle est la structure d'un article scientifique ?","o":["IMRaD, pour introduction, méthodes, résultats et discussion","TIMER, pour titre, introduction, méthodes, études et résultats","PICO, pour population, intervention, comparaison et outcome","IRDM, pour introduction, résultats, discussion et méthodes"],"r":0,"e":"IMRaD = Introduction, Méthodes, Résultats and Discussion.","s":1},{"q":"Quelles bases de données sont pertinentes en kiné ? (plusieurs)","o":["PubMed","PEDro","Cochrane","TikTok","Facebook"],"r":[0,1,2],"e":"PubMed (biomédical général), PEDro (spécifique physio avec score qualité), Cochrane (revues systématiques).","s":1},{"q":"Question : « Le tabagisme augmente-t-il le risque de lombalgie chronique ? » → type :","o":["Intervention","Pronostic","Étiologie","Diagnostic"],"r":2,"e":"Recherche d'un facteur de risque / cause = étiologie.","s":1},{"q":"Une bonne question de recherche est : (plusieurs)","o":["Claire","Précise","Faisable","Pertinente cliniquement","Provocatrice"],"r":[0,1,2,3],"e":"Claire, précise, faisable, pertinente, ancrée dans un besoin réel.","s":1},{"q":"Quels outils sont des méthodes qualitatives ?","o":["Des entretiens semi-dirigés","Des groupes de discussion","Une analyse de variance","Une mesure au dynamomètre"],"r":[0,1],"e":"Entretiens et focus groups explorent vécu et perceptions (qualitatif). Les groupes de discussion sont des focus groups.","s":1},{"q":"« Quelle est la prévalence de la lombalgie chez les physios européens ? » → type :","o":["Une question d'intervention","Une question d'étiologie, sur un facteur","Une question de fréquence","Une question de diagnostic"],"r":2,"e":"Mesure de fréquence dans une population = prévalence (étude transversale). Il s'agit de prévalence.","s":1},{"q":"Quel paradigme étudie la réalité OBJECTIVE et mesurable ?","o":["Qualitatif","Quantitatif","Mixte","Phénoménologique"],"r":1,"e":"Quantitatif = mesures chiffrées, variables quantifiables, statistiques.","s":1},{"q":"L'EBP n'est PAS :","o":["Une démarche systématique","Une remise en question des pratiques routinières","Une application aveugle de la littérature","Une intégration des valeurs du patient"],"r":2,"e":"L'EBP n'est pas une application aveugle : elle intègre l'expertise clinique et le patient.","s":1},{"q":"Une étude de cohorte est utile pour :","o":["Mesurer un OR","Suivre l'évolution dans le temps","Tester la spécificité d'un test","Évaluer la validité d'une échelle"],"r":1,"e":"Cohorte = suivi prospectif/rétrospectif d'un groupe → étude de l'évolution (pronostic).","s":1},{"q":"Quelles méthodes correspondent à une question d'intervention ?","o":["Les essais randomisés contrôlés","Les méta-analyses d'essais","Les études transversales","Les études phénoménologiques"],"r":[0,1],"e":"RCT et méta-analyses sont les méthodes de référence pour les questions d'intervention.","s":1},{"q":"Dans PICO, le « C » désigne :","o":["Les conditions de l'étude","La comparaison, ou le comparateur","La conclusion tirée des résultats de l'essai","Les critères, d'inclusion et d'exclusion"],"r":1,"e":"C = Comparison : placebo, soins standards, autre technique…","s":1},{"q":"Une intuition clinique est :","o":["Une preuve scientifique valable, en soi","Un point de départ d'hypothèse, pas une preuve","Une preuve acceptable si plusieurs cliniciens la partagent","Une donnée suffisante pour publier dans Cochrane"],"r":1,"e":"Une intuition n'est jamais une preuve, mais peut générer une hypothèse à tester.","s":1},{"q":"Le « Pivot Shift » est un test :","o":["Un test de la douleur du genou","Un test diagnostique de rupture du LCA","Un test de prévalence de la lésion du LCA","Un test de qualité de vie"],"r":1,"e":"Le pivot shift est un test diagnostique d'instabilité du LCA.","s":1},{"q":"Quelles affirmations sur la méthode scientifique sont vraies ? (plusieurs)","o":["Elle évite les erreurs d'interprétation","Elle produit des résultats reproductibles","Elle s'appuie sur l'intuition seule","Elle inclut la réplication par d'autres équipes"],"r":[0,1,3],"e":"La méthode scientifique évite l'intuition seule, vise la reproductibilité, et la réplication.","s":1},{"q":"Parmi les objectifs du module MTR, le cours cite :","o":["Éviter les croyances, les biais et les pratiques dépassées","Apprendre à publier dans une revue internationale","Maîtriser les statistiques avancées et leurs logiciels","Devenir chercheur à plein temps, en laboratoire"],"r":0,"e":"S'y ajoutent la prise de décisions éclairées, la critique des publications et la proposition d'interventions efficientes.","s":1},{"q":"La science est décrite dans le cours comme :","o":["Un processus d'amélioration continue, pas une certitude","Une certitude établie, qui ne se discute plus une fois prouvée","Un ensemble de croyances partagées","Une opinion majoritaire des experts"],"r":0,"e":"Elle s'oppose aux croyances immédiates et vise à décrire, expliquer et prédire.","s":1},{"q":"Le caractère « contrôlé » de l'investigation selon Kerlinger signifie :","o":["Limiter les biais, par exemple avec des consignes identiques","Suivre un protocole précis à chaque séance","Remettre en question ses hypothèses, sans les défendre à tout prix","Utiliser des données mesurables"],"r":0,"e":"Les quatre propriétés sont empirique, systématique, critique et contrôlée. Le même environnement en fait partie.","s":1},{"q":"Le caractère « systématique » de l'investigation implique :","o":["Suivre un protocole précis, comme la même échelle à chaque séance","Accepter, sans cesse, la remise en question de ses hypothèses","Mesurer les données avec des outils","Limiter les biais de l'environnement"],"r":0,"e":"Le caractère critique impose, lui, d'accepter de remettre en question ses hypothèses.","s":1},{"q":"Parmi les étapes de la méthode scientifique figure, après la collecte des données :","o":["L'analyse statistique, puis l'interprétation","La publication directe des données brutes","La formulation de l'hypothèse, à partir des données","Le choix du protocole de mesure"],"r":0,"e":"La réplication par d'autres équipes clôt le cycle. Viennent ensuite la publication et la réplication.","s":1},{"q":"Dans le raisonnement hypothético-déductif appliqué au genou, la prédiction est :","o":["Que si l'on renforce, la douleur diminuera","Que le quadriceps est déficitaire","Que le genou est douloureux, à la descente des escaliers","Que la force est mesurable au dynamomètre"],"r":0,"e":"La séquence va de l'observation à la question, l'hypothèse, la prédiction, le test, les données, la conclusion et l'adaptation.","s":1},{"q":"Une bonne question de recherche est :","o":["Claire, précise, faisable et cliniquement pertinente","Large et ouverte, pour explorer","Théorique, sans lien avec la pratique","Originale avant tout, même si elle est infaisable en pratique"],"r":0,"e":"Elle conditionne le choix du type d'étude approprié. Elle s'ancre dans un besoin réel.","s":1},{"q":"Une question de type « fréquence » appelle :","o":["Une étude transversale, qui mesure la prévalence","Un essai randomisé, qui compare deux groupes","Une étude de cohorte, qui suit des patients","Une étude cas-témoins, avec un odds ratio"],"r":0,"e":"Les études cas-témoins répondent aux questions étiologiques, par l'odds ratio.","s":1},{"q":"Une question qualitative appelle :","o":["Des entretiens et des focus groups, sur le vécu","Un essai randomisé, sur deux groupes","Une étude transversale, sur un grand échantillon représentatif","Une méta-analyse des essais publiés"],"r":0,"e":"C'est le sixième type de question clinique, celui de l'expérience patient. Ils explorent vécu et perceptions.","s":1},{"q":"Une question de pronostic appelle :","o":["Des études de cohorte, qui suivent l'évolution","Un essai randomisé, qui compare deux traitements actifs","Une étude cas-témoins, rétrospective","Une étude transversale, à un instant donné"],"r":0,"e":"Le délai de récupération après rupture du LCA en est un exemple.","s":1},{"q":"Les mesures associées à une question diagnostique comprennent :","o":["Sensibilité, spécificité et valeurs prédictives","L'odds ratio, avec son intervalle de confiance","Le risque relatif et le nombre de sujets à traiter","La prévalence, puis l'incidence"],"r":0,"e":"Elles se présentent classiquement sous forme d'un tableau 2×2. S'y ajoutent les rapports de vraisemblance et l'aire sous la courbe ROC.","s":1},{"q":"Un test spécifique se caractérise par :","o":["Peu de faux positifs","Peu de faux négatifs","Une forte sensibilité","Une prévalence élevée"],"r":0,"e":"La sensibilité détecte les vrais positifs et limite les faux négatifs.","s":1},{"q":"Dans PICO, le « O » désigne :","o":["L'outcome, c'est-à-dire le résultat mesuré","L'objectif général de l'étude","L'observation, c'est-à-dire l'examen initial","L'opérateur booléen de recherche"],"r":0,"e":"Le T de PICOT ajoute la dimension temporelle, par exemple 6 mois.","s":1},{"q":"Dans PICO, le « P » désigne :","o":["Le patient ou la population","Le protocole de l'étude, détaillé","Le paramètre principal mesuré","La preuve scientifique"],"r":0,"e":"Le I désigne l'intervention et le C la comparaison.","s":1},{"q":"La structure IMRaD désigne :","o":["Introduction, Méthodes, Résultats et Discussion","Idée, Méthode, Recherche, Données","Introduction, Matériel, Résultats, Débat","Investigation, Mesure, Rapport, Diffusion"],"r":0,"e":"C'est la structure standard d'un article scientifique.","s":1},{"q":"Ne constituent pas des preuves, selon le cours :","o":["L'intuition, le témoignage et la tradition","Les essais randomisés contrôlés, en double aveugle","Les méta-analyses de la littérature, dans la Cochrane","Les études de cohorte prospectives"],"r":0,"e":"C'est le principe même de l'empirisme scientifique. Le « ça marche pour moi » n'en est pas une non plus.","s":1},{"q":"Parmi les contenus du module, le cours cite :","o":["Recherche, preuves, rédaction et lecture critique","Les seules statistiques, descriptives ou non","La seule rédaction d'un mémoire","La seule lecture critique d'articles publiés"],"r":0,"e":"Les bases citées sont PubMed, Cochrane et PEDro. Concepts de l'investigation, processus de recherche, pratique fondée sur l'évidence, organisation et méthodes.","s":1},{"q":"La science est essentielle en kinésithérapie parce que :","o":["Le domaine évolue et s'appuie sur des preuves","Les patients l'exigent de plus en plus","C'est une obligation légale pour exercer","Les statistiques sont utiles au quotidien"],"r":0,"e":"Il s'agit de raisonner comme un chercheur, même sans l'être. Les recommandations reposent sur des preuves.","s":1},{"q":"Le quatrième pilier de la science, après observation, question et expérimentation, est :","o":["L'analyse, c'est-à-dire l'interprétation des données","La publication, c'est-à-dire la diffusion des résultats","La réplication par une autre équipe","L'hypothèse de départ, posée avant l'étude"],"r":0,"e":"L'analyse de la marche illustre l'observation et les tests fonctionnels l'expérimentation.","s":1},{"q":"La variable indépendante correspond :","o":["À ce que l'on manipule, donc à la cause","À ce que l'on mesure, donc à l'effet","Au résultat final de l'étude","À un biais de sélection"],"r":0,"e":"La variable dépendante est ce que l'on mesure, c'est-à-dire l'effet.","s":1},{"q":"Que signifie PBE ?","o":["Pratique basée sur l'expérience du praticien","Pratique basée sur l'évidence, ou sur les preuves","Plan basé sur l'étude des cas","Protocole basé sur l'expertise, celle des pairs reconnus"],"r":1,"e":"PBE = Pratique Basée sur l'Évidence (en anglais : Evidence-Based Practice). En anglais, Evidence-Based Practice.","s":2},{"q":"Quelles sont les 3 étapes de la démarche PBE ?","o":["Poser une question, chercher les preuves, les appliquer","Observer le patient, mesurer ses progrès, puis enfin conclure","Définir, tester, puis publier","Diagnostiquer, traiter, puis suivre"],"r":0,"e":"PBE = 1) question PICO, 2) chercher les meilleures preuves, 3) appliquer au patient avec raisonnement. La question se formule en PICO.","s":2},{"q":"Que signifie PIE ?","o":["Pratique Indépendante de l'Évidence","Pratique Informée par l'Évidence","Protocole d'Investigation Empirique","Procédure d'Intervention Expérimentale"],"r":1,"e":"PIE = Pratique Informée par l'Évidence (Evidence-Informed Practice).","s":2},{"q":"Quelle approche est plus souple et adaptable ?","o":["PBE","PIE","Aucune","Les deux à parts égales"],"r":1,"e":"La PIE utilise les preuves sans les suivre de manière automatique : plus adaptable.","s":2},{"q":"Quels sont les 3 piliers de l'EBP selon Sackett (2000) ?","o":["Preuve, expertise clinique, valeurs et préférences du patient","Recherche, théorie et application clinique","Patient, médecin et infirmier, réunis autour d'une même décision","Diagnostic, traitement et rééducation"],"r":0,"e":"Sackett : 1) meilleure preuve scientifique, 2) expertise clinique, 3) valeurs et préférences du patient.","s":2},{"q":"Quelles sont les 5 étapes de la PBE (les 5 A) ?","o":["Ask, Acquire, Appraise, Apply, Analyze","Ask, Answer, Analyse, Apply, Achieve","Acquire, Adapt, Apply, Approve, Audit","Assess, Ask, Apply, Adjust, Affirm"],"r":0,"e":"Les 5 A : Ask (question), Acquire (chercher), Appraise (évaluer), Apply (appliquer), Analyze (observer/ajuster).","s":2},{"q":"Dans la pyramide de l'évidence, quel niveau est au SOMMET (plus robuste) ?","o":["Les opinions d'experts reconnus du domaine","Les séries de cas publiées","Les études transversales","Les revues systématiques et méta-analyses"],"r":3,"e":"Au sommet : revues systématiques, méta-analyses, guidelines (moins de biais).","s":2},{"q":"À la base de la pyramide de l'évidence on trouve : (plusieurs)","o":["Opinions d'experts","Études transversales","Séries de cas","Méta-analyses"],"r":[0,1,2],"e":"Base : opinions d'experts, études transversales, séries de cas (utiles si littérature rare mais peu fiables).","s":2},{"q":"Au niveau intermédiaire de la pyramide on trouve :","o":["Cohortes, cas-témoins et essais contrôlés","Méta-analyses, uniquement","Opinions d'experts, uniquement","Séries de cas, exclusivement, et avis d'experts"],"r":0,"e":"Niveau intermédiaire : cohortes, cas-témoins, essais cliniques contrôlés.","s":2},{"q":"La PBE dévalorise : (plusieurs)","o":["Les pratiques basées sur l'habitude","Les protocoles non validés","« On a toujours fait comme ça »","Les lectures critiques d'articles"],"r":[0,1,2],"e":"La PBE dévalorise les pratiques par habitude/intuition, les protocoles non validés et les traditions sans fondement.","s":2},{"q":"L'étape « APPRAISE » consiste à :","o":["Poser la question en format PICO","Chercher les articles dans les bases","Évaluer la méthodologie et les biais","Diffuser ses résultats auprès de l'équipe soignante"],"r":2,"e":"Appraise = évaluer la qualité méthodologique : randomisation, biais, applicabilité…","s":2},{"q":"L'étape « ACQUIRE » consiste à :","o":["Acheter du matériel de rééducation neuf","Chercher des preuves dans des bases reconnues","Mettre à jour son curriculum vitae","Acquérir de nouveaux patients pour le cabinet"],"r":1,"e":"Acquire = rechercher des preuves dans des bases reconnues (PubMed, Cochrane, PEDro).","s":2},{"q":"Quelle est la différence majeure entre PBE et PIE ?","o":["La PIE est moins scientifique que la PBE","La PBE applique, la PIE adapte au contexte","La PIE ne concerne que la kinésithérapie","Aucune différence, ce sont des synonymes"],"r":1,"e":"PBE = rigueur du protocole. PIE = adaptation au patient (peur, comorbidités, contexte).","s":2},{"q":"Quelles sont les 4 limites de la littérature qui justifient la PIE ?","o":["Données incomplètes, conflits d'études, autres populations","Plagiat, fraude, manque d'auteurs et retards de publication","Peu de pays, langue, format et coût des articles","Absence d'essais, doublons, biais d'auteurs et coût"],"r":0,"e":"4 limites : données parfois incomplètes, conflits d'études, populations différentes des patients réels, contraintes du patient. Les contraintes du patient en font aussi partie.","s":2},{"q":"Quel est l'objectif COMMUN de la PBE et de la PIE ?","o":["Augmenter le nombre de publications du service de soins","Améliorer la qualité des soins et des décisions","Réduire les coûts de santé, uniquement","Standardiser la prise en charge de tous"],"r":1,"e":"Objectif commun : améliorer la qualité des soins et rendre les décisions plus fiables, justifiées, cohérentes, adaptées.","s":2},{"q":"« Faire une recherche documentaire » = ?","o":["Produire des données nouvelles, sur le terrain","Consulter les preuves déjà existantes","Recruter des participants pour une étude","Concevoir un protocole d'essai"],"r":1,"e":"Recherche documentaire = consulter les revues, méta-analyses et guidelines existantes.","s":2},{"q":"« Réaliser une étude scientifique » = ?","o":["Lire une méta-analyse récente","Produire de nouvelles données","Recopier une thèse existante","Suivre une recommandation"],"r":1,"e":"Réaliser une étude = concevoir protocole, recruter, collecter, analyser, publier.","s":2},{"q":"Quels documents sont des études secondaires ?","o":["RCT","Revue systématique","Méta-analyse","Étude de cas"],"r":[1,2],"e":"Études secondaires = synthèse de plusieurs études primaires (revues systématiques, méta-analyses).","s":2},{"q":"L'EBPP (APTA) inclut :","o":["Jugement clinique expert","Préférences du patient","Preuves scientifiques","Contexte social et environnemental","Le seul avis du thérapeute"],"r":[0,1,2,3],"e":"L'EBPP (APTA) = jugement clinique + préférences patient + preuves + contexte social/environnemental.","s":2},{"q":"Le « ça marche sur moi » est considéré comme :","o":["Une preuve forte","Un avis valable","Pas une preuve scientifique","Une preuve de niveau intermédiaire"],"r":2,"e":"« Ça marche sur moi », « j'ai vu ça sur Instagram » : non considérés comme preuves.","s":2},{"q":"En lecture stratégique d'un article, on lit dans cet ordre :","o":["Titre → Abstract → Méthode → Conclusion","Conclusion → Discussion → Méthode","Tout linéairement","Méthode uniquement"],"r":0,"e":"Lecture stratégique : titre → abstract → méthode → conclusion.","s":2},{"q":"L'étape « ASK » de la PBE consiste à :","o":["Formuler une question clinique précise","Acheter des articles payants en ligne","Demander l'avis d'un expert","Rédiger l'introduction du mémoire"],"r":0,"e":"Ask = formuler la question clinique précise, souvent en PICO. On la formule souvent en PICO.","s":2},{"q":"Quel est le piège de baser sa pratique sur la seule expertise clinique ?","o":["Aucun","Elle peut être biaisée","C'est toujours préférable","Elle n'a pas de valeur"],"r":1,"e":"L'expérience seule peut être biaisée. D'où la combinaison preuves + expertise + patient.","s":2},{"q":"Une revue systématique fait partie de :","o":["Études primaires","Études secondaires","Guidelines","Opinions d'experts"],"r":1,"e":"Revue systématique = étude secondaire (synthèse d'études primaires).","s":2},{"q":"Lors d'un mémoire, par quel type de preuve commencer la recherche ?","o":["Les études de cas isolés","Les revues systématiques et les guidelines","Les vidéos publiées sur YouTube","Les forums de discussion en ligne, comme Reddit"],"r":1,"e":"Toujours commencer par le sommet : revues systématiques et guidelines.","s":2},{"q":"Vrai ou faux : la PBE rejette l'avis du patient.","o":["Vrai","Faux"],"r":1,"e":"Faux : le patient est au centre de la décision (valeurs et préférences = 3ᵉ pilier de Sackett).","s":2},{"q":"Quel exemple ILLUSTRE la PIE ?","o":["Appliquer le protocole de la méta-analyse à un patient âgé sans modification","Adapter les charges pour un patient âgé arthrosique malgré le protocole standard","Refuser tout traitement non randomisé","Ignorer les préférences du patient"],"r":1,"e":"PIE = adaptation contextualisée : on respecte la preuve mais on ajuste selon le patient.","s":2},{"q":"La pyramide de l'évidence repose sur quel critère principal ?","o":["Le coût des études","Le risque de biais","Le nombre d'auteurs","La langue de publication"],"r":1,"e":"Les études sont hiérarchisées en fonction du risque de biais.","s":2},{"q":"Quels exemples sont des PRATIQUES DÉVALORISÉES par la PBE ? (plusieurs)","o":["« Ça marche sur moi »","Lecture critique d'articles","« J'ai vu ça sur Instagram »","Protocoles validés","« On a toujours fait comme ça »"],"r":[0,2,4],"e":"Les pratiques basées sur opinion personnelle, mode et tradition non fondée sont dévalorisées.","s":2},{"q":"Selon le cours, la PBE ne cherche pas à :","o":["Détruire la pratique clinique","L'éclairer","Renforcer le raisonnement","Améliorer les soins"],"r":0,"e":"La PBE ne cherche pas à détruire la pratique clinique, mais à l'éclairer.","s":2},{"q":"La PBE se définit comme une démarche :","o":["Rigoureuse et systématique, avec une mise à jour continue","Souple et adaptable, selon le patient et le contexte de soin","Intuitive, fondée sur l'expérience","Empirique, au sens du bon sens commun"],"r":0,"e":"Ses trois étapes sont identifier la question par PICO, chercher et sélectionner les preuves, appliquer au patient avec raisonnement justifié.","s":2},{"q":"La PIE reconnaît notamment :","o":["La variabilité des patients et les limites de la littérature","La seule rigueur scientifique, sans adaptation au patient traité","L'absence totale de preuves fiables","L'inutilité de tous les protocoles validés"],"r":0,"e":"Elle utilise les preuves sans automatisme.","s":2},{"q":"Dans l'exemple de la tendinopathie d'Achille :","o":["La PBE suit le protocole, la PIE l'adapte au patient","Les deux appliquent le protocole de façon identique","La PIE rejette le protocole excentrique","La PBE adapte le protocole, la PIE l'applique tel quel au patient"],"r":0,"e":"L'objectif commun reste d'améliorer la qualité des soins. L'adaptation tient compte de l'appréhension, des comorbidités ou du calendrier sportif.","s":2},{"q":"Le pilier « expertise clinique » de Sackett recouvre :","o":["L'expérience, la technique et le raisonnement du professionnel","Les méta-analyses récentes du domaine","Les préférences et les attentes du patient, dans sa prise en charge","Le contexte social et familial"],"r":0,"e":"Le cours rappelle que la science seule ne suffit pas et que l'expérience seule peut être biaisée.","s":2},{"q":"Le pilier « valeurs et préférences du patient » recouvre :","o":["Ses objectifs, ses limites et sa motivation","Sa seule motivation à guérir vite","Ses seules limites physiques","Son diagnostic médical, posé par le médecin prescripteur"],"r":0,"e":"Le patient est au centre de la démarche. Sa représentation personnelle de la santé en fait partie.","s":2},{"q":"Parmi ce que la PBE valorise, le cours cite :","o":["Les protocoles validés et la lecture critique","Les traditions transmises par les aînés","L'intuition du praticien le plus expérimenté","Les protocoles dits magiques"],"r":0,"e":"La lecture critique porte sur le niveau de preuve et la qualité. Les protocoles sont reproductibles et mesurables, avec une mise à jour continue.","s":2},{"q":"L'étape APPLY des 5 A consiste à :","o":["Appliquer la preuve en tenant compte du patient","Formuler la question en format PICO","Chercher les preuves dans les bases","Observer le résultat et ajuster la prise en charge du patient"],"r":0,"e":"ANALYZE clôt le cycle en observant le résultat pour ajuster.","s":2},{"q":"Le cycle des 5 A se justifie par le fait que :","o":["La pratique est dynamique et la science évolue sans cesse","Les protocoles changent chaque année, par décision officielle","Les patients varient d'une séance à l'autre","Les bases de données se mettent à jour la nuit"],"r":0,"e":"C'est ce qui impose la mise à jour continue.","s":2},{"q":"Dans la pyramide de l'évidence, le niveau intermédiaire comprend :","o":["Les cohortes, les cas-témoins et les essais contrôlés","Les méta-analyses et les revues systématiques de qualité","Les opinions d'experts, faute de mieux","Les séries de cas et les rapports isolés"],"r":0,"e":"La base, d'une fiabilité faible, reste utile quand la littérature est rare. Leur fiabilité varie selon la rigueur.","s":2},{"q":"Plus on monte dans la pyramide de l'évidence :","o":["Moins il y a de risque de biais","Plus il y a d'études","Plus les études sont récentes","Plus l'échantillon est grand"],"r":0,"e":"C'est le critère principal sur lequel repose la hiérarchie.","s":2},{"q":"La PIE insiste sur trois dimensions :","o":["L'adaptabilité, la contextualisation et l'individualisation","La rigueur, la reproductibilité et la mesure","La preuve, l'expertise et le patient","Les étapes ask, acquire et appraise de la démarche des preuves"],"r":0,"e":"Quatre limites de la littérature la justifient.","s":2},{"q":"Parmi les quatre limites de la littérature justifiant la PIE figure :","o":["Des populations d'étude différentes des patients réels","L'absence totale de données dans tous les domaines de la rééducation","Le coût élevé des études publiées","La langue de publication, souvent l'anglais"],"r":0,"e":"S'y ajoutent les données incomplètes, les conflits entre études et les contraintes de vie du patient.","s":2},{"q":"Le cycle de la PIE suit l'ordre :","o":["Consulter, intégrer l'expérience et le patient, ajuster","Ajuster, consulter, puis intégrer l'expérience","Tenir compte du patient, puis consulter l'évidence","Intégrer l'expérience, puis consulter l'évidence"],"r":0,"e":"L'ajustement se décompose en observer, analyser, modifier et réévaluer. On consulte d'abord l'évidence.","s":2},{"q":"Dans l'exemple de la lombalgie aiguë chez un patient anxieux, la PIE propose :","o":["Une négociation, une éducation graduée et des exercices","L'application stricte du protocole, sans discussion","Le repos, comme le demande le patient","L'abstention thérapeutique, en attendant que la peur passe"],"r":0,"e":"La science recommande activité physique et éducation, mais le patient craint le mouvement. Les exercices proposés sont acceptables pour le patient.","s":2},{"q":"Le risque propre à la PBE est :","o":["Une standardisation excessive","Une subjectivité excessive","Un manque de rigueur","Une absence de preuve"],"r":0,"e":"Le risque de la PIE est au contraire la subjectivité.","s":2},{"q":"L'EBPP selon l'APTA ajoute aux trois piliers :","o":["Le contexte social et environnemental","Les statistiques de l'étude","La réplication des résultats","Le coût du traitement pour la société et le patient"],"r":0,"e":"C'est l'approche la plus complète, qui connecte science et humain.","s":2},{"q":"La recherche documentaire se distingue de l'étude scientifique en ce qu'elle :","o":["Consulte les preuves existantes, quand l'étude en produit","Produit des données nouvelles, comme une étude scientifique","Ne concerne que les chercheurs professionnels","Exige un protocole expérimental validé"],"r":0,"e":"La première est le quotidien du clinicien, la seconde celui du chercheur.","s":2},{"q":"L'étude scientifique suppose :","o":["Un protocole, un recrutement, une collecte et une analyse","Consulter des revues, puis en faire une synthèse critique","Lire des guidelines et les appliquer","Faire une revue narrative de la littérature"],"r":0,"e":"Revue narrative, systématique, méta-analyse et guidelines relèvent, elles, de la recherche documentaire. La publication vient ensuite.","s":2},{"q":"Pour un mémoire, le cours recommande de commencer par :","o":["Les revues systématiques","Les séries de cas","Les opinions d'experts","Les études transversales"],"r":0,"e":"Elles occupent le sommet de la pyramide, avec les méta-analyses et les guidelines.","s":2},{"q":"L'objectif commun de la PBE et de la PIE est :","o":["Améliorer les soins et fiabiliser les décisions","La standardisation de toutes les prises en charge","La production de nouvelles données","La publication d'articles scientifiques"],"r":0,"e":"Elles diffèrent par la priorité donnée à la rigueur ou à l'adaptabilité. Les décisions deviennent aussi cohérentes et adaptées.","s":2},{"q":"Un projet de recherche décrit : (plusieurs)","o":["Ce que l'on veut étudier","Pourquoi on veut l'étudier","Comment on va le faire","Ce que l'on fera des résultats","Combien on va le vendre"],"r":[0,1,2,3],"e":"Un projet décrit le quoi, le pourquoi, le comment et l'usage des résultats.","s":3},{"q":"Quelles sont les 6 étapes du processus de recherche ?","o":["Question, revue, méthodologie, collecte, diffusion, application","Question, méthodologie, conclusion, article, application","Observation, hypothèse, test, mesure, données, interprétation","Idée, plan, action, évaluation, modification, diffusion"],"r":0,"e":"6 étapes : Question, Revue de littérature, Méthodologie, Collecte/analyse, Diffusion, Application.","s":3},{"q":"Si on étudie l'effet du temps d'étude sur la note d'examen, le temps d'étude est :","o":["Variable dépendante","Variable indépendante","Variable parasite","Hypothèse"],"r":1,"e":"Le temps d'étude est manipulé/contrôlé → variable indépendante (cause).","s":3},{"q":"La note à l'examen dans le même exemple est :","o":["VI","VD","Hypothèse","Outcome subjectif"],"r":1,"e":"La note mesurée est l'effet observé → variable dépendante.","s":3},{"q":"Le PICO sert à :","o":["À mesurer la douleur","À structurer une question clinique","À faire des statistiques","À citer des auteurs dans la bibliographie"],"r":1,"e":"PICO est un outil de structuration d'une question clinique : Patient, Intervention, Comparaison, Outcome.","s":3},{"q":"Dans PICOT, le T désigne :","o":["Le type d'étude choisi","Le temps, soit la durée du suivi","Le traitement, appliqué au groupe expérimental","Le tableau des résultats"],"r":1,"e":"T = Temps (durée d'intervention ou de suivi).","s":3},{"q":"Que signifie l'acronyme FINER ?","o":["Faisable, Intéressant, Nouveau, Éthique, Relevant","Facile, Investigable, Notable, Évalué, Reproductible","Final, Important, Notable, Évalué, Rigoureux","Fait, Initié, Noté, Évident, Réalisable"],"r":0,"e":"FINER : Faisable, Intéressant, Nouveau, Éthique, Relevant (pertinent).","s":3},{"q":"Que signifie SMART ?","o":["Spécifique, mesurable, atteignable, relevant, temporel","Simple, modéré, adapté, réel, tangible","Smart, mesuré, adapté, rapide, théorique","Spécifique, mesuré, argumenté, réfléchi, tendu vers un but"],"r":0,"e":"SMART = Spécifique, Mesurable, Atteignable, Relevant, Temporel.","s":3},{"q":"FINER s'applique à :","o":["À l'évaluation d'un objectif","À l'évaluation d'une question de recherche","À la qualité d'un article publié","Au coût d'une étude et à son financement public"],"r":1,"e":"FINER évalue si une question de recherche vaut la peine d'être transformée en projet.","s":3},{"q":"SMART s'applique à :","o":["L'évaluation d'un objectif","L'évaluation d'une question","La qualité d'un instrument","L'évaluation d'un patient"],"r":0,"e":"SMART évalue la qualité des objectifs spécifiques d'une étude.","s":3},{"q":"« Les évaluations régulières sont-elles positives pour les étudiants ? » est :","o":["Une bonne question scientifique, bien posée","Une mauvaise question, car vague et non mesurable","Une question quantitative, mesurée par un questionnaire validé","Une question qualitative, explorée par entretiens"],"r":1,"e":"« Positives » est trop vague, non mesurable. Préférer : assiduité, note finale, etc.","s":3},{"q":"Une bonne question de recherche doit être : (plusieurs)","o":["Éthique","Pertinente","Quantifiable","Alignée avec les objectifs","Provocatrice"],"r":[0,1,2,3],"e":"Éthique, pertinente, quantifiable, alignée.","s":3},{"q":"En PICO, dans la question : « L'aquathérapie réduit-elle la douleur des lombalgiques chroniques vs kiné conventionnelle ? », le P est :","o":["L'aquathérapie","Les lombalgiques chroniques","La kiné conventionnelle","La douleur"],"r":1,"e":"P = Population = lombalgiques chroniques.","s":3},{"q":"Dans la même question, le I est :","o":["Aquathérapie","Lombalgie","Kiné conventionnelle","Douleur"],"r":0,"e":"I = Intervention testée = aquathérapie.","s":3},{"q":"Dans la même question, le C est :","o":["La lombalgie chronique","L'aquathérapie de 6 mois","La kinésithérapie conventionnelle","La douleur et la qualité de vie du patient"],"r":2,"e":"C = Comparaison = kiné conventionnelle.","s":3},{"q":"Dans la même question, le O est :","o":["L'aquathérapie de 6 mois","La lombalgie chronique","La kinésithérapie, du groupe contrôle","La douleur, et la qualité de vie"],"r":3,"e":"O = Outcome = ce qu'on mesure = douleur, qualité de vie.","s":3},{"q":"Quelle source NE PEUT PAS servir de point de départ pour un projet ?","o":["Une observation clinique","Une controverse dans la littérature","Un problème clinique fréquent","Un rêve sans rapport avec la kiné"],"r":3,"e":"Un projet part d'une observation, controverse ou problème clinique réel.","s":3},{"q":"« Pertinence (Why ?) » d'un projet répond à :","o":["Comment va-t-on faire l'étude ?","Pourquoi ce problème est-il important ?","Combien ça coûte, et qui va financer l'étude ?","Quand faut-il publier ?"],"r":1,"e":"Pertinence = pourquoi le problème est important (fréquence, handicap, coût).","s":3},{"q":"« Signification (What ?) » répond à :","o":["Quel matériel faut-il prévoir ?","Que va apporter ce travail de nouveau ?","Qui va réaliser l'étude ?","Quand faut-il publier les résultats, et dans quelle revue ?"],"r":1,"e":"Signification = ce que votre étude va apporter de nouveau ou utile.","s":3},{"q":"Le consentement éclairé sert à :","o":["Faire signer un papier seulement","Respecter la liberté du participant","Imposer le protocole","Limiter les coûts"],"r":1,"e":"Le consentement éclairé respecte la liberté du participant : il peut se retirer à tout moment.","s":3},{"q":"Les principes éthiques essentiels en recherche incluent : (plusieurs)","o":["Ne jamais nuire aux participants","Garantir la confidentialité des données","Laisser la liberté de se retirer","Imposer le protocole sans informer"],"r":[0,1,2],"e":"Principes : non-nuisance, consentement éclairé, confidentialité, liberté de retrait.","s":3},{"q":"Une revue de littérature consiste à :","o":["Empiler des résumés d'articles","Faire une synthèse critique et organisée","Lire tous les articles existants","Recopier les résumés des articles les plus cités"],"r":1,"e":"Revue de littérature = synthèse critique, analyse, comparaison, lacunes (PAS un résumé).","s":3},{"q":"Une revue de littérature permet : (plusieurs)","o":["De situer le travail dans son contexte","De montrer l'état des connaissances","D'identifier des angles originaux","D'inventer les résultats manquants de l'étude"],"r":[0,1,2],"e":"La revue situe le travail, montre l'état des connaissances, identifie les lacunes et angles originaux.","s":3},{"q":"Quel exemple est un OBJECTIF GÉNÉRAL ?","o":["« Démontrer l'effet du massage chez les lombalgiques »","« Comparer les résultats entre hommes et femmes »","« Mesurer l'EVA au début et à la fin de l'étude »","« Vérifier le lien entre la douleur et le sommeil »"],"r":0,"e":"Objectif général = vision globale (le « grand objectif »). Les autres sont spécifiques. Il porte sur la douleur et la qualité de vie.","s":3},{"q":"Quels exemples sont des OBJECTIFS SPÉCIFIQUES ? (plusieurs)","o":["Identifier les domaines de QdV qui s'améliorent le plus","Comparer les résultats par sous-groupes","Démontrer l'effet global d'un programme","Vérifier la corrélation douleur ↔ QdV"],"r":[0,1,3],"e":"Les objectifs spécifiques sont les sous-questions concrètes (corrélation, comparaisons, mesures).","s":3},{"q":"Quel critère SMART manque dans : « Évaluer la douleur lombaire après aquathérapie » ?","o":["Le critère temporel, faute de durée","Le critère spécifique","Le critère atteignable","Le critère mesurable, faute d'échelle validée"],"r":0,"e":"Manque le T (temporel) : « après 6 mois » par exemple.","s":3},{"q":"Quel critère FINER concerne la nouveauté ?","o":["F","I","N","E"],"r":2,"e":"N = Nouveau : apporte-t-il quelque chose d'original ?","s":3},{"q":"Le projet doit être reproductible parce que :","o":["C'est plus rapide à réaliser","Un autre chercheur doit pouvoir refaire l'étude","Cela permet de gagner de l'argent","Cela limite le nombre de participants nécessaires à l'étude"],"r":1,"e":"La reproductibilité = pilier scientifique : un autre doit pouvoir refaire l'étude.","s":3},{"q":"Lien rédaction : le projet structure :","o":["L'introduction, les méthodes et la discussion du mémoire","Seulement l'introduction du mémoire","Seulement les résultats, présentés sous forme de tableaux","Aucune partie, le projet restant à part"],"r":0,"e":"Le projet structure l'introduction (problème), les méthodes (type, population, outils) et la discussion.","s":3},{"q":"Vrai ou faux : un projet bien défini limite les biais et perte de données.","o":["Vrai","Faux"],"r":0,"e":"Vrai : un bon projet limite les erreurs, biais, et perte de données.","s":3},{"q":"Le projet de recherche est comparé dans le cours à :","o":["Une carte routière","Un plan d'architecte","Une recette","Un protocole médical"],"r":0,"e":"Il décrit le quoi, le pourquoi, le comment et les implications.","s":3},{"q":"Parmi les rôles d'un bon projet, le cours cite :","o":["La crédibilité auprès du jury et du comité d'éthique","La rapidité de réalisation, au détriment de la rigueur","Un coût réduit au minimum","La garantie d'être publié"],"r":0,"e":"S'y ajoutent la limitation des erreurs, la reproductibilité et l'utilité clinique des résultats. Le directeur de mémoire est aussi concerné.","s":3},{"q":"L'étape 5 du processus de recherche correspond à :","o":["Partager les résultats, par communication ou publication","Collecter et analyser les données, avec des tests statistiques","Concevoir le plan d'étude et le protocole","Appliquer les résultats en pratique"],"r":0,"e":"L'étape 6, dernière, est l'application des résultats à la pratique clinique.","s":3},{"q":"L'étape 2 du processus de recherche, la revue de littérature, correspond dans le mémoire :","o":["Au cadre théorique","À la section Matériels et Méthodes","À la section Résultats","À la discussion"],"r":0,"e":"L'étape 3, la méthodologie, correspond aux Matériels et Méthodes.","s":3},{"q":"Parmi les manières de commencer un projet, « observer » signifie :","o":["Repérer les patients qui progressent mal ou très vite","Lire la littérature récente du domaine étudié","Interroger sa pratique et ses habitudes de soin","Critiquer les preuves disponibles sur le sujet"],"r":0,"e":"Lire, rechercher, observer, interroger et critiquer constituent les cinq portes d'entrée.","s":3},{"q":"Pour la recherche bibliographique, le cours recommande des mots-clés :","o":["En anglais de préférence, avec des filtres","En français, pour mieux comprendre les résultats","Dans la langue du patient","Sans aucun filtre, pour tout voir"],"r":0,"e":"PubMed, PEDro, Cochrane et Google Scholar sont les bases citées.","s":3},{"q":"La pertinence d'un projet, le « Why », répond à la question :","o":["Pourquoi ce problème est-il important ?","Que changera votre travail, concrètement ?","Comment le mesurer précisément ?","Qui sera inclus, et selon quels critères ?"],"r":0,"e":"La signification, le « What », répond à ce que le travail changera. Il est fréquent, handicapant ou coûteux.","s":3},{"q":"Une bonne question de recherche doit notamment être :","o":["Éthique, pertinente, quantifiable et alignée avec les objectifs","Originale avant tout, même si elle est infaisable","Large, pour couvrir tous les aspects possibles du sujet à étudier","Théorique, sans application clinique"],"r":0,"e":"Elle oriente la revue de littérature, la méthodologie, les variables, les outils et les analyses.","s":3},{"q":"Dans FINER, le « I » signifie :","o":["Intéressant, pour le chercheur et pour d'autres","Important, pour la santé publique","Innovant, par rapport aux études antérieures","Indépendant de tout financement"],"r":0,"e":"Les cinq critères sont Faisable, Intéressant, Nouveau, Éthique et Relevant.","s":3},{"q":"Dans FINER, le « R » signifie :","o":["Relevant, donc important pour la pratique","Reproductible par une autre équipe","Rigoureux dans sa méthode et sa mesure","Randomisé, avec un groupe contrôle"],"r":0,"e":"FINER s'applique au projet, SMART aux objectifs.","s":3},{"q":"Dans SMART, le « A » signifie :","o":["Atteignable, donc réalisable","Analysable, donc mesurable","Approprié, donc adapté","Appliqué, donc clinique"],"r":0,"e":"Les cinq critères sont Spécifique, Mesurable, Atteignable, Relevant et Temporel.","s":3},{"q":"Parmi les principes éthiques essentiels, le cours cite :","o":["Ne pas nuire, consentement, retrait libre, confidentialité","Le seul consentement écrit du patient, avant l'étude","La seule confidentialité des données recueillies","La seule liberté de se retirer de l'étude en cours"],"r":0,"e":"Ils encadrent tout projet impliquant des participants. S'y ajoutent la minimisation des risques et le respect des valeurs et de la culture.","s":3},{"q":"La revue de littérature n'est pas :","o":["Un simple résumé d'articles, sans analyse critique","Une synthèse organisée des connaissances","Une comparaison des méthodologies, étude par étude","Une identification des lacunes de la littérature existante"],"r":0,"e":"Elle synthétise, compare les méthodologies, souligne les limites, met en évidence les controverses et identifie les lacunes. C'est une analyse critique et structurée.","s":3},{"q":"Parmi ce que permet la revue de littérature, le cours cite :","o":["D'éviter de refaire ce qui est déjà résolu","De produire des données nouvelles sur le terrain","De recruter des patients","De publier plus vite un article"],"r":0,"e":"Elle situe le travail dans son contexte scientifique et identifie les angles originaux.","s":3},{"q":"L'objectif général se distingue des objectifs spécifiques par :","o":["Sa vision globale, les spécifiques en étant les étapes","Sa précision, plus grande que celle des objectifs spécifiques","Sa mesurabilité, toujours chiffrée","Sa durée, plus longue que celle des autres"],"r":0,"e":"Comparer des sous-groupes selon l'âge ou le sexe relève des objectifs spécifiques.","s":3},{"q":"Dans l'exemple SMART cité, le « M » est assuré par :","o":["L'échelle visuelle analogique","La durée de 6 mois","La lombalgie chronique de l'adulte","L'aquathérapie en piscine"],"r":0,"e":"Le T est assuré par les 6 mois et le R par l'importance de la lombalgie.","s":3},{"q":"Parmi les manières de commencer un projet, « critiquer » consiste à se demander :","o":["Est-ce vraiment prouvé, ou serait-ce un placebo ?","Que dit la littérature récente, sur ce sujet précis ?","Qui sont mes patients habituels ?","Combien cela coûte-t-il au patient ?"],"r":0,"e":"C'est la cinquième porte d'entrée, après lire, rechercher, observer et interroger. On se demande aussi s'il existe une méthode plus efficace ou plus sûre.","s":3},{"q":"Le projet limite les erreurs telles que :","o":["Les biais, les pertes de données et la mauvaise méthode","Les seules erreurs de calcul","Les seuls biais de sélection","Les seules pertes de données, en cours de suivi des patients"],"r":0,"e":"Un projet bien défini rend aussi l'étude reproductible.","s":3},{"q":"La variable dépendante correspond :","o":["À ce que l'on mesure, l'effet observé","À ce que l'on manipule, la cause","À un facteur externe, à contrôler","À la population étudiée, prise dans son ensemble"],"r":0,"e":"La note à l'examen ou la douleur à l'EVA en sont des exemples ; la variable indépendante est la cause supposée.","s":3},{"q":"La question de recherche est décrite comme :","o":["Le cœur du projet, qui sert de fil rouge","Une formalité administrative à remplir","Une étape secondaire, après la méthode","Un résumé de l'introduction"],"r":0,"e":"Elle détermine la méthodologie, les variables, les outils et les analyses.","s":3},{"q":"La méthodologie répond à la question :","o":["Pourquoi ?","Quoi ?","Comment ?","Quand ?"],"r":2,"e":"La question = pourquoi. La méthodologie = comment.","s":4},{"q":"Une méthodologie doit être : (plusieurs)","o":["Claire","Justifiée","Reproductible","Cachée"],"r":[0,1,2],"e":"Claire (étape par étape), justifiée (cohérente avec les objectifs), reproductible.","s":4},{"q":"La méthodologie conditionne :","o":["La validité, la fiabilité et la crédibilité","Le seul coût de l'étude, en euros","Le nombre d'auteurs, et leur ordre","La langue de publication, et la revue choisie pour l'article"],"r":0,"e":"La méthodologie conditionne la validité, la fiabilité et la crédibilité de la recherche.","s":4},{"q":"Validité = ?","o":["Mesure-t-on bien ce qu'on prétend mesurer ?","Si on refait, obtient-on la même chose ?","Le test est-il rapide ?","Le test est-il bon marché ?"],"r":0,"e":"Validité = mesurer ce qu'on prétend mesurer (ex. EVA pour la douleur).","s":4},{"q":"Fiabilité = ?","o":["Mesurer bien la chose que l'on prétend mesurer","La reproductibilité de la mesure","Le coût de l'instrument","La vitesse de la mesure"],"r":1,"e":"Fiabilité = en refaisant la mesure dans les mêmes conditions, on obtient des résultats similaires.","s":4},{"q":"Quel paradigme étudie la réalité subjective (vécu, perceptions) ?","o":["Quantitatif","Qualitatif","Mixte uniquement","Empirique"],"r":1,"e":"La recherche qualitative étudie le subjectif : expériences, perceptions, émotions.","s":4},{"q":"Quelles méthodes sont qualitatives ?","o":["Des entretiens semi-dirigés","Des groupes de discussion","L'observation participante","Un essai randomisé contrôlé"],"r":[0,1,2],"e":"Qualitatif : entretiens, focus groups, observation participante. RCT = quantitatif. Les groupes de discussion sont les focus groups.","s":4},{"q":"Une étude expérimentale se caractérise par :","o":["Le chercheur n'intervient pas","Le chercheur manipule une variable","Seules les revues sont expérimentales","Pas de variables"],"r":1,"e":"Étude expérimentale = le chercheur manipule (intervention) une variable.","s":4},{"q":"Une étude observationnelle :","o":["Manipule activement les variables","Observe sans modifier","Est toujours une revue","N'a pas de population"],"r":1,"e":"Observationnelle = pas d'intervention du chercheur, observation.","s":4},{"q":"Quel design observationnel pour mesurer une PRÉVALENCE ?","o":["Cas-témoins","Cohorte","Transversale","RCT"],"r":2,"e":"Étude transversale = mesure à un instant T (prévalence).","s":4},{"q":"Quel design observationnel pour suivre l'évolution dans le temps ?","o":["Transversale","Cohorte","Cas-témoins","RCT"],"r":1,"e":"Cohorte = suivi d'un groupe dans le temps (prospectif ou rétrospectif).","s":4},{"q":"Quel design observationnel pour rechercher des facteurs de risque ?","o":["Transversale","Cas-témoins","RCT","Méta-analyse"],"r":1,"e":"Cas-témoins : compare cas (avec maladie) vs témoins (sans) → facteurs de risque.","s":4},{"q":"Que signifie RCT ?","o":["Recherche Clinique Théorique","Essai Clinique Randomisé","Revue Critique des Thèses","Recherche Comparée des Tests"],"r":1,"e":"RCT = Randomized Controlled Trial = essai clinique randomisé.","s":4},{"q":"Quel est le « gold standard » de la recherche clinique ?","o":["Une étude transversale","Une étude de cas unique","Un essai clinique randomisé","Une opinion d'expert"],"r":2,"e":"RCT = gold standard : randomisation + groupe expérimental + groupe contrôle. Il associe randomisation et groupe contrôle.","s":4},{"q":"Une étude quasi-expérimentale est :","o":["Avec randomisation, et avec intervention","Sans randomisation, mais avec intervention","Sans intervention, et sans randomisation","Sans participants, sur simulation"],"r":1,"e":"Quasi-expérimentale = même logique que l'expérimentale, mais SANS randomisation.","s":4},{"q":"La randomisation sert à :","o":["Augmenter le coût de l'étude","Rendre les groupes comparables au départ","Cacher l'intervention au patient et au thérapeute","Augmenter la taille de l'échantillon"],"r":1,"e":"La randomisation rend les groupes comparables et réduit les biais initiaux.","s":4},{"q":"Une variable indépendante est :","o":["Ce qu'on mesure comme effet","Ce qu'on manipule ou compare","Un facteur confondant","Un outcome"],"r":1,"e":"VI = cause manipulée ou comparée (intervention, durée, intensité).","s":4},{"q":"Une variable dépendante est :","o":["Ce qu'on manipule","Ce qu'on mesure comme effet","La randomisation","La taille de l'échantillon"],"r":1,"e":"VD = effet observé/mesuré (douleur, force, amplitude…).","s":4},{"q":"Une variable confondante (parasite) est :","o":["Une variable que l'on souhaite manipuler","Un facteur externe qui influence l'effet","La variable principale de l'étude","Le résultat principal mesuré"],"r":1,"e":"Variable confondante = facteur externe qui peut influencer la VD (âge, sexe, médicaments…). Il doit être contrôlé.","s":4},{"q":"Dans la question « L'ultrason réduit-il la douleur ? », l'ultrason est :","o":["VI","VD","Confondante","Outcome"],"r":0,"e":"L'ultrason est l'intervention manipulée → VI.","s":4},{"q":"L'hypothèse nulle (H0) affirme :","o":["Qu'il existe un effet réel de l'intervention","Qu'il n'existe aucune relation","Que l'intervention augmente la douleur","Que l'étude n'est pas publiable"],"r":1,"e":"H0 = absence de relation entre VI et VD. On la teste en stats.","s":4},{"q":"L'hypothèse alternative (H1) :","o":["Affirme l'existence d'une relation","Affirme l'absence de tout effet","Est toujours rejetée à la fin","Est une autre façon de nommer l'hypothèse nulle"],"r":0,"e":"H1 = il existe une relation. Si on rejette H0, on donne du poids à H1.","s":4},{"q":"La population est :","o":["Tous les individus concernés par la question","Le seul groupe étudié dans l'essai","Les participants exclus de l'étude","Les chercheurs et les évaluateurs de l'étude publiée"],"r":0,"e":"Population = ensemble visé par la question. Échantillon = sous-ensemble étudié.","s":4},{"q":"Un bon échantillon doit être : (plusieurs)","o":["Représentatif","Suffisant en nombre","Sélectionné selon une méthode claire","Le plus petit possible"],"r":[0,1,2],"e":"Représentatif, suffisant (puissance statistique), méthode claire.","s":4},{"q":"L'échantillon de commodité est :","o":["Aléatoire, par tirage au sort","Non aléatoire, avec les patients disponibles","Toujours représentatif de la population","Préférable scientifiquement à tout autre mode de sélection"],"r":1,"e":"Échantillon de commodité = non aléatoire, à mentionner comme limite.","s":4},{"q":"Pour mesurer la douleur, quel outil est validé ?","o":["EVA / NRS","Goniomètre","Dynamomètre","TUG"],"r":0,"e":"EVA (Échelle Visuelle Analogique) et NRS mesurent la douleur.","s":4},{"q":"Pour mesurer la qualité de vie : (plusieurs)","o":["SF-36","EQ-5D","ODI","TUG"],"r":[0,1,2],"e":"SF-36, EQ-5D, ODI (Oswestry Disability Index) sont validés pour la QdV/fonction.","s":4},{"q":"Pour mesurer l'amplitude articulaire :","o":["Goniomètre et inclinomètre","Dynamomètre et électromyogramme","Échelle visuelle analogique","Questionnaire SF-36"],"r":0,"e":"Goniomètre et inclinomètre mesurent l'amplitude (mobilité).","s":4},{"q":"Pour mesurer l'équilibre :","o":["BERG, TUG et miniBEST","ODI et Roland-Morris","EVA, NRS et McGill","SF-36, EQ-5D et WOMAC réunis"],"r":0,"e":"Tests d'équilibre : BERG (Berg Balance Scale), TUG (Timed Up and Go), miniBEST.","s":4},{"q":"Un instrument de mesure doit être : (plusieurs)","o":["Validé","Fiable","Adapté à la population","Cher"],"r":[0,1,2],"e":"Un bon instrument est validé, fiable et adapté à l'âge/langue/culture.","s":4},{"q":"La méthodologie est décrite comme :","o":["La colonne vertébrale de l'étude, entre question et terrain","Une formalité administrative, exigée par l'université","La partie statistique du mémoire, en fin de document","Le calendrier prévisionnel de l'étude, mois par mois"],"r":0,"e":"Si la question répond au pourquoi, la méthodologie répond au comment.","s":4},{"q":"Une méthodologie « justifiée » signifie que :","o":["Chaque choix est cohérent avec les objectifs","Le lecteur comprend étape par étape","Un autre chercheur peut refaire l'étude","Les résultats sont significatifs"],"r":0,"e":"Les trois qualités requises sont claire, justifiée et reproductible.","s":4},{"q":"La méthodologie occupe, dans le processus de recherche :","o":["La 3ᵉ étape","La 1ʳᵉ étape","La 2ᵉ étape","La dernière étape"],"r":0,"e":"Elle suit la question et la revue de littérature, et précède la collecte et l'analyse.","s":4},{"q":"La fiabilité s'évalue notamment par :","o":["Le test-retest et l'accord inter-évaluateurs","L'échelle visuelle analogique de la douleur","Le questionnaire SF-36 de qualité de vie","Le goniomètre seul, sans autre outil"],"r":0,"e":"La validité répond, elle, à la question de savoir si l'on mesure bien ce que l'on prétend mesurer.","s":4},{"q":"La roadmap méthodologique comporte :","o":["Dix éléments, du paradigme au budget","Cinq éléments, de la question au plan","Trois éléments, du design à l'analyse","Quinze éléments, de la question jusqu'à la publication finale"],"r":0,"e":"Elle inclut paradigme, type d'étude, design, population et échantillon, outcomes, instruments, procédures, analyse, planning et budget.","s":4},{"q":"Le paradigme qualitatif permet :","o":["De comprendre en profondeur et d'identifier des thèmes","De mesurer et de généraliser les résultats obtenus","De comparer statistiquement deux groupes","De quantifier l'efficacité d'un traitement"],"r":0,"e":"En kinésithérapie, les deux sont complémentaires : le quantitatif pour l'efficacité, le qualitatif pour l'expérience.","s":4},{"q":"Parmi les méthodes quantitatives citées figurent :","o":["Les essais, les cohortes et le dynamomètre","Les entretiens semi-dirigés, en face à face","Les focus groups, en petits groupes","L'observation participante, sur le terrain"],"r":0,"e":"Ces trois dernières relèvent du paradigme qualitatif. L'EMG et les questionnaires standardisés en font aussi partie.","s":4},{"q":"Les études observationnelles se caractérisent par :","o":["Rapides, peu coûteuses, mais faibles sur la causalité","Une force probante élevée, comme les essais","Une manipulation de la variable indépendante par le chercheur","Une randomisation des participants"],"r":0,"e":"Les études expérimentales testent, elles, des relations de cause à effet. Elles sont aussi plus proches de la vraie vie.","s":4},{"q":"La notion de « contrôle » dans une étude expérimentale consiste à :","o":["Neutraliser les facteurs externes, comme le thérapeute ou la durée","Randomiser les participants entre plusieurs groupes de traitement","Manipuler la variable indépendante, ou cause","Mesurer l'effet sur la variable dépendante"],"r":0,"e":"La manipulation est l'application de l'intervention et la randomisation la répartition au hasard. Même thérapeute, même durée, mêmes consignes, même environnement.","s":4},{"q":"L'étude quasi-expérimentale se définit par :","o":["La logique d'une étude expérimentale, mais sans randomisation","L'absence de groupe contrôle et d'intervention","L'absence d'intervention du chercheur","Une randomisation partielle, sur la moitié seulement des participants"],"r":0,"e":"Elle est plus simple, mais expose à davantage de biais, notamment de sélection.","s":4},{"q":"Une variable confondante est :","o":["Un facteur externe à contrôler, qui influence l'effet mesuré","La cause manipulée par le chercheur","L'effet mesuré chez les participants","Un outil de mesure de l'effet, validé et fiable chez les patients"],"r":0,"e":"Âge, sexe, activité physique, médicaments et pathologies associées en sont des exemples.","s":4},{"q":"L'hypothèse se définit comme :","o":["Une proposition testable reliant la cause et l'effet","Une question ouverte sur le sujet","Une conclusion tirée des résultats","Une observation clinique faite au cours de la pratique quotidienne"],"r":0,"e":"En statistiques, c'est l'hypothèse nulle que l'on teste. Elle relie la variable indépendante et la variable dépendante.","s":4},{"q":"Si les résultats sont improbables sous l'hypothèse nulle :","o":["On la rejette, au profit de l'hypothèse alternative","On l'accepte, car les résultats sont rares","On conclut à l'absence de tout effet","On recommence l'étude avec davantage de patients"],"r":0,"e":"L'hypothèse nulle affirme qu'il n'existe aucune relation entre les variables.","s":4},{"q":"Un bon échantillon doit être :","o":["Représentatif, assez grand et bien sélectionné","Le plus grand possible, quel qu'en soit le coût","Le plus accessible, pour recruter vite et sans frais","Homogène, pour éviter toute variabilité"],"r":0,"e":"L'échantillonnage aléatoire donne la meilleure représentativité mais est plus difficile à mettre en œuvre. La taille assure la puissance statistique.","s":4},{"q":"L'échantillonnage de commodité :","o":["Prend les patients disponibles, moins représentatifs","Est aléatoire, par tirage au sort","Est le plus représentatif de tous les modes d'échantillonnage","Est interdit en recherche clinique"],"r":0,"e":"Dans l'échantillonnage aléatoire, chaque individu a la même probabilité d'être inclus. C'est plus simple, mais cela doit être mentionné en limite.","s":4},{"q":"Pour mesurer la fonction, les instruments cités sont :","o":["L'ODI, le Roland-Morris et le WOMAC","L'EVA, le NRS et le questionnaire McGill","Le BERG, le TUG et le miniBEST","Le SF-36, l'EQ-5D et le WHOQOL"],"r":0,"e":"Le SF-36 et l'EQ-5D mesurent la qualité de vie, le BERG et le TUG l'équilibre.","s":4},{"q":"Pour mesurer la douleur, les instruments cités sont :","o":["L'EVA, le NRS et le McGill","Le goniomètre et l'inclinomètre","Le dynamomètre, l'EMG et la plateforme de force","Le miniBEST, le BERG et le TUG"],"r":0,"e":"L'inclinomètre et le goniomètre mesurent la mobilité, le dynamomètre la force.","s":4},{"q":"Un bon instrument de mesure doit être :","o":["Validé, fiable et adapté à la population étudiée","Récent, numérique et peu coûteux à l'achat pour le cabinet","Peu coûteux, quelle que soit sa validité","Numérique, pour un recueil automatique"],"r":0,"e":"Les outcomes doivent par ailleurs être observables, mesurables et alignés sur les objectifs. L'adaptation porte sur l'âge, la langue et la culture.","s":4},{"q":"Le design transversal est utile pour :","o":["La prévalence et les associations simples à un instant T","Le pronostic, en suivant les patients sur plusieurs années","Les facteurs de risque, de façon rétrospective","La causalité, par comparaison de groupes"],"r":0,"e":"Le cas-témoins, rétrospectif, sert aux facteurs de risque et la cohorte au risque, au pronostic et à l'évolution.","s":4},{"q":"Le RCT est qualifié de gold standard parce qu'il associe :","o":["Randomisation, groupe expérimental et groupe contrôle","Un grand échantillon, et une longue durée","Une longue durée et un financement public","Un financement important et plusieurs centres d'essai"],"r":0,"e":"C'est ce qui lui confère la plus forte capacité à établir une causalité.","s":4},{"q":"Les 3 questions à se poser lors d'une recherche : Quel type de recherche, quel type de preuves, et :","o":["Combien de pages faut-il lire ?","Où chercher, dans quelles bases ?","Qui l'a écrit, et dans quelle université travaille-t-il ?","Combien cela coûte-t-il d'accéder aux articles ?"],"r":1,"e":"3 questions : Type de question → Type d'étude → Base de données adaptée.","s":5},{"q":"Une étude PRIMAIRE est :","o":["Une revue systématique de plusieurs essais publiés","Une étude qui produit des données nouvelles","Une recommandation de bonne pratique","Un avis d'expert publié"],"r":1,"e":"Études primaires = données nouvelles : RCT, cohortes, cas-témoins, séries de cas, transversales. Essais randomisés, cohortes, cas-témoins, séries de cas et études transversales.","s":5},{"q":"Une étude SECONDAIRE est :","o":["Une étude qui produit des données nouvelles","Une synthèse de plusieurs études primaires","Un cas clinique détaillé, publié dans une revue","Une recommandation de bonne pratique"],"r":1,"e":"Études secondaires = revues systématiques, méta-analyses, overviews.","s":5},{"q":"Les guidelines (NICE, GIN…) sont :","o":["Des cas cliniques, commentés par des experts","Des recommandations officielles, rédigées par des experts","Des opinions individuelles de praticiens","Des moteurs de recherche spécialisés dans les articles médicaux"],"r":1,"e":"Guidelines = recommandations officielles avec grades et niveaux de preuve.","s":5},{"q":"Quelle base est SPÉCIFIQUE à la kinésithérapie et propose un score de qualité ?","o":["PubMed","Cochrane","PEDro","Google Scholar"],"r":2,"e":"PEDro = base spécifique physiothérapie avec score de qualité méthodologique.","s":5},{"q":"Cochrane Reviews est connu pour :","o":["Ses revues systématiques de haute qualité","Ses opinions d'experts reconnus dans le monde entier","Ses blogs de patients et de soignants","Ses vidéos de formation"],"r":0,"e":"Cochrane Reviews = revues systématiques de référence.","s":5},{"q":"L'opérateur booléen AND :","o":["Élargit les résultats, par l'union","Réduit les résultats, par l'intersection","Exclut un terme de la recherche, comme NOT","Trie les résultats par date"],"r":1,"e":"AND impose la présence conjointe → réduit les résultats.","s":5},{"q":"L'opérateur booléen OR :","o":["Élargit les résultats, utile pour les synonymes","Réduit les résultats, par intersection","Exclut un terme de la recherche, comme le fait NOT","Trie les résultats par auteur"],"r":0,"e":"OR élargit la recherche → utile pour les synonymes.","s":5},{"q":"L'opérateur booléen NOT :","o":["Réduit en excluant un terme","Élargit","Fait l'intersection","Inverse les résultats"],"r":0,"e":"NOT exclut les articles contenant un terme.","s":5},{"q":"<code>child*</code> est un exemple de :","o":["Opérateur booléen","Troncature","Expression exacte","Filtre"],"r":1,"e":"Troncature : <code>child*</code> trouve child, children, childhood.","s":5},{"q":"Pour chercher l'expression exacte « low back pain », on utilise :","o":["Des parenthèses","Des guillemets","AND","Un astérisque"],"r":1,"e":"Les guillemets « » servent à chercher une expression exacte.","s":5},{"q":"Que signifie MeSH ?","o":["Medical Subject Headings","Medical Search Helper","Methodological Search Hierarchy","Medline Subject Hub"],"r":0,"e":"MeSH = Medical Subject Headings = vocabulaire contrôlé de PubMed.","s":5},{"q":"Les MeSH terms permettent : (plusieurs)","o":["D'éviter les ambiguïtés de langue","De regrouper les articles sous un descripteur","De trouver moins d'articles pertinents","De gagner en pertinence"],"r":[0,1,3],"e":"MeSH : évite ambiguïtés, regroupe les synonymes, augmente la pertinence.","s":5},{"q":"Dans une requête PubMed, les parenthèses servent à :","o":["Structurer la logique","Citer un auteur","Faire une troncature","Ouvrir un menu"],"r":0,"e":"Les parenthèses précisent ce qui est regroupé : (A OR B) AND C ≠ A OR (B AND C).","s":5},{"q":"Le résultat de <code>(\"low back pain\" OR backache) AND \"bed rest\"</code> :","o":["Plus de résultats que l'autre placement des parenthèses","Moins de résultats que l'autre placement des parenthèses","Le même nombre, quel que soit le placement","Un nombre imprévisible, selon la base"],"r":1,"e":"Premier : intersection avec bed rest = peu d'articles. Second : OR final ouvre tout backache → beaucoup plus. L'autre placement est (low back pain AND bed rest) OR backache.","s":5},{"q":"Quels filtres peut-on appliquer en recherche avancée ? (plusieurs)","o":["Date","Type d'étude","Langue","Âge","Couleur"],"r":[0,1,2,3],"e":"Filtres : date, type d'étude, langue, âge, espèce humaine, etc.","s":5},{"q":"Un journal grand public est :","o":["Évalué par les pairs, avant publication","Écrit par des journalistes, pour vulgariser","La source principale d'un mémoire de fin d'études","Indexé dans PubMed comme les revues"],"r":1,"e":"Journal grand public ≠ périodique scientifique évalué par les pairs.","s":5},{"q":"Un périodique scientifique est :","o":["Écrit par des journalistes, pour le grand public curieux","Écrit par des chercheurs et évalué par les pairs","Toujours gratuit et en libre accès","Une vidéo de vulgarisation en ligne"],"r":1,"e":"Périodique scientifique = pairs reviewed, méthodes/résultats/discussion.","s":5},{"q":"Quels outils de gestion bibliographique sont recommandés ? (plusieurs)","o":["Zotero","Mendeley","EndNote","TikTok"],"r":[0,1,2],"e":"Zotero, Mendeley, EndNote = outils pour gérer les références et la biblio.","s":5},{"q":"Quelle question est trop large ?","o":["« La physiothérapie traite-t-elle la douleur ? »","« L'aquathérapie réduit-elle la douleur des lombalgiques ? »","« Quels exercices proposer après une ligamentoplastie du genou ? »","« Le massage diminue-t-il l'anxiété avant une chirurgie ? »"],"r":0,"e":"« La physio traite-t-elle la douleur ? » est trop vague pour être exploitable. Elle est trop vague pour être exploitable.","s":5},{"q":"Quelle question est trop spécifique ?","o":["« L'aquathérapie 3 fois par semaine chez des femmes de 52 ans ? »","« L'exercice est-il efficace, en général, chez tous les patients ? »","« Quels patients récupèrent le mieux à 6 mois d'une chirurgie ? »"],"r":0,"e":"Trop spécifique : aucun article ne correspondra exactement à ces critères. L'IMC et la durée de 28 jours étaient aussi précisés.","s":5},{"q":"Quel niveau de la pyramide est le plus robuste ?","o":["Les séries de cas publiées en revue","Les études transversales de prévalence","Les méta-analyses et revues systématiques","Les avis d'experts reconnus"],"r":2,"e":"Sommet de la pyramide : méta-analyses, revues systématiques, guidelines. Les guidelines en font aussi partie.","s":5},{"q":"PubMed est principalement utilisé pour :","o":["Les vidéos médicales","Les références biomédicales","Les médicaments uniquement","Le grand public"],"r":1,"e":"PubMed = immense base biomédicale.","s":5},{"q":"Quelle stratégie de recherche est correcte pour la lombalgie en kiné ?","o":["Chercher sur Google et lire le premier blog venu en tête","Chercher sur PEDro, PubMed et Cochrane, avec des filtres","Consulter uniquement Wikipédia","Lire les forums de patients, au hasard"],"r":1,"e":"Bonne approche : bases scientifiques + filtres pertinents + évaluation qualité. On évalue ensuite la qualité des études.","s":5},{"q":"Pour une question d'INTERVENTION, on cherche idéalement dans :","o":["Cochrane Reviews et PEDro","Les forums de patients en ligne","SciELO, et seulement elle","Aucune base en particulier"],"r":0,"e":"Question intervention → essais cliniques/méta-analyses → Cochrane, PEDro, PubMed.","s":5},{"q":"<code>physiotherapy OR \"physical therapy\"</code> sert à :","o":["Réduire les résultats","Trouver des synonymes","Exclure un terme","Trier par date"],"r":1,"e":"OR pour couvrir les synonymes : physiotherapy / physical therapy.","s":5},{"q":"Vrai ou faux : un seul article suffit pour conclure scientifiquement.","o":["Vrai","Faux"],"r":1,"e":"Faux : une seule étude présente un risque accru de biais.","s":5},{"q":"Les guidelines (NICE, GIN) fournissent : (plusieurs)","o":["Conduites recommandées","Grades de recommandation","Niveaux de preuve","Études de cas individuelles"],"r":[0,1,2],"e":"Guidelines : conduites recommandées, grades, niveaux de preuve.","s":5},{"q":"Quel est l'ordre de lecture stratégique d'un article ?","o":["Titre, résumé, méthode, puis conclusion","Bibliographie, puis conclusion, puis titre","Méthode, puis résultats seulement","Discussion uniquement, en détail"],"r":0,"e":"Titre → Abstract → Méthode → Conclusion = lecture stratégique efficace.","s":5},{"q":"Avant de lancer une recherche, on doit : (plusieurs)","o":["Préparer une liste de mots-clés et synonymes","Choisir le champ de recherche","Combiner AND/OR/NOT","Utiliser des guillemets pour les expressions","Rédiger la discussion de l'article"],"r":[0,1,2,3],"e":"Préparation : liste de mots-clés/synonymes, champ choisi, opérateurs, guillemets, troncatures. La discussion s'écrit à la toute fin du travail, une fois les résultats obtenus.","s":5},{"q":"La recherche scientifique est décrite comme :","o":["Une démarche organisée, avec des règles et des étapes","Une exploration libre, au hasard des moteurs de recherche","Une simple lecture d'articles","Un travail purement statistique"],"r":0,"e":"Elle enchaîne question, recherche d'informations, analyse critique et application raisonnée. Ce n'est pas une chasse au hasard sur Google.","s":5},{"q":"Pour une question d'étiologie, les études adaptées sont :","o":["Les cas-témoins et les cohortes","Les essais randomisés contrôlés","Les études transversales","Les études qualitatives"],"r":0,"e":"Les questions de fréquence appellent des études transversales et celles d'expérience patient des études qualitatives.","s":5},{"q":"La limite principale d'une étude primaire est :","o":["Une seule étude expose davantage au risque de biais","Son coût, souvent trop élevé pour un étudiant en kinésithérapie","Sa durée de réalisation, souvent longue","Son ancienneté de publication"],"r":0,"e":"Les études secondaires, qui synthétisent plusieurs études primaires, sont très rentables pour un étudiant.","s":5},{"q":"Les « overviews » correspondent à :","o":["Des revues de revues","Des essais randomisés","Des séries de cas","Des guidelines"],"r":0,"e":"Ils appartiennent aux études secondaires, avec les revues systématiques et les méta-analyses.","s":5},{"q":"Les guidelines fournissent :","o":["Des conduites recommandées, avec grades et niveaux de preuve","Des données brutes, issues d'essais non publiés et non relus","Des protocoles expérimentaux","Des analyses statistiques détaillées"],"r":0,"e":"NICE, GIN et les sociétés savantes en sont les émetteurs cités.","s":5},{"q":"La stratégie de recherche recommandée consiste à :","o":["Partir du haut de la pyramide, puis descendre si besoin","Commencer par les séries de cas","Commencer par les études primaires, puis remonter vers les revues","Chercher au hasard des résultats"],"r":0,"e":"Cela maximise la robustesse des preuves trouvées en premier. On commence par les guidelines et les revues systématiques.","s":5},{"q":"La base PEDro se distingue par :","o":["Sa spécialisation en kinésithérapie et son score de qualité","Sa gratuité totale pour tous les utilisateurs","Son ancienneté, plus grande que PubMed","Sa taille, la plus grande de toutes les bases médicales au monde"],"r":0,"e":"Cochrane Reviews est la référence des études secondaires, PubMed et Cochrane Clinical Trials des études primaires.","s":5},{"q":"Parmi les bases généralistes, le cours cite :","o":["Google Scholar, B-On et SciELO","PubMed, PEDro et Cochrane","Cochrane, et elle seule","NICE, GIN et les sociétés savantes nationales"],"r":0,"e":"Chaque type de preuve a ses bases privilégiées.","s":5},{"q":"Une fiche de base de données contient notamment :","o":["Titre, auteurs, année, journal, résumé et DOI","Le seul titre de l'article, sans les auteurs","Le seul résumé de l'article, sans le titre","Le seul DOI de l'article, sans aucun lien"],"r":0,"e":"C'est cette structuration qui permet la recherche par mots-clés, filtres et équations complexes. Les mots-clés et le lien vers le texte intégral en font aussi partie.","s":5},{"q":"La recherche simple se caractérise par :","o":["Un seul champ, large, pour tâter le terrain","Plusieurs champs combinés, en mode avancé","L'usage des MeSH, pour préciser","L'usage des filtres, par date"],"r":0,"e":"La recherche avancée combine champs, opérateurs booléens, filtres et termes MeSH.","s":5},{"q":"Les six éléments de la recherche avancée comprennent :","o":["MeSH, booléens, troncatures, parenthèses et filtres","Les seuls opérateurs booléens","Les seuls termes MeSH, en anglais","Les seuls filtres, par date, par langue et par type d'étude"],"r":0,"e":"Ils se combinent pour construire une équation de recherche précise. Les opérateurs de proximité en font aussi partie.","s":5},{"q":"Les termes MeSH permettent :","o":["D'éviter les ambiguïtés et de regrouper les synonymes","D'élargir la recherche au hasard","De trier tous les résultats, du plus récent au plus ancien","De filtrer les articles par langue"],"r":0,"e":"Si les mots libres donnent peu de résultats, il faut passer au MeSH. Les articles sont regroupés sous un même descripteur.","s":5},{"q":"La troncature « behavio?r » permet de retrouver :","o":["Behavior et behaviour","Behavior seulement","Les seuls pluriels","Les seuls adjectifs"],"r":0,"e":"Le caractère * sert, lui, aux variantes de fin de mot, comme child* ou diabet*.","s":5},{"q":"Sans guillemets, une expression de plusieurs mots :","o":["Peut être lue mot par mot, ce qui réduit la pertinence","Est toujours cherchée telle quelle, dans l'ordre","Est ignorée par le moteur de recherche","Génère une erreur de syntaxe"],"r":0,"e":"Les guillemets imposent l'expression exacte, comme « low back pain ».","s":5},{"q":"L'exemple des parenthèses montre que la requête « (low back pain OR backache) AND bed rest » donne :","o":["556 articles, contre 88 601 pour l'autre placement","88 601 articles, contre 556 pour l'autre placement","Le même nombre d'articles, quel que soit le placement choisi","Aucun résultat, la requête étant mal formée"],"r":0,"e":"La position des parenthèses change donc radicalement le résultat.","s":5},{"q":"L'opérateur NOT a pour effet :","o":["D'exclure un terme","D'élargir les résultats","De réduire par intersection","De chercher une expression exacte"],"r":0,"e":"AND réduit par intersection et OR élargit par union, utile pour les synonymes.","s":5},{"q":"Une question trop spécifique est problématique parce qu'elle :","o":["Elle restreint trop le champ de recherche","Elle est trop large pour donner des résultats exploitables","Elle n'est pas mesurable en pratique","Elle manque de pertinence clinique"],"r":0,"e":"Une question équilibrée se situe entre « la physiothérapie traite-t-elle la douleur ? » et une description démographique exhaustive.","s":5},{"q":"Parmi les filtres disponibles en recherche avancée, le cours cite :","o":["La période, le type d'étude, l'âge, la langue et l'espèce","Le seul type d'étude, sans autre critère","La seule date de publication, à l'année près, sans autre critère","Le seul nom de l'auteur principal"],"r":0,"e":"Ils affinent une requête déjà construite avec MeSH et opérateurs.","s":5},{"q":"Pour une question de pronostic, les études adaptées sont :","o":["Les études de cohorte","Les essais randomisés","Les cas-témoins","Les études qualitatives"],"r":0,"e":"Le délai de retour au sport après une entorse de cheville en est un exemple.","s":5},{"q":"Le bas de la pyramide des preuves comprend :","o":["Les rapports et séries de cas, les avis d'experts","Les essais randomisés, contrôlés et en aveugle","Les méta-analyses et les revues systématiques récentes","Les recommandations officielles des sociétés savantes"],"r":0,"e":"Sa puissance est limitée, mais il reste utile quand la littérature est rare. Les petites études observationnelles en font aussi partie.","s":5},{"q":"Un travail scientifique est structuré en :","o":["Une seule partie, le texte rédigé","Trois parties, pré-textuelle, textuelle, post-textuelle","Deux parties, l'introduction et la conclusion","Quatre parties, introduction, méthodes, résultats, références"],"r":1,"e":"3 grandes parties : pré-textuels / textuels / post-textuels.","s":6},{"q":"Quels éléments sont PRÉ-textuels ? (plusieurs)","o":["Couverture","Page de garde","Résumé","Bibliographie","Index"],"r":[0,1,2,4],"e":"Pré-textuels : couverture, page de garde, dédicace, résumé, abréviations, index. Bibliographie = post-textuel.","s":6},{"q":"Quels éléments sont TEXTUELS ? (plusieurs)","o":["Introduction","Méthodologie","Résultats","Annexes","Discussion","Conclusion"],"r":[0,1,2,4,5],"e":"Textuels = cœur scientifique : Intro, Revue litt, Méthodo, Résultats, Discussion, Conclusion.","s":6},{"q":"Quels éléments sont POST-textuels ? (plusieurs)","o":["Bibliographie","Appendices","Annexes","Introduction"],"r":[0,1,2],"e":"Post-textuels : bibliographie, appendices, annexes.","s":6},{"q":"Pour un travail de recherche LONG, sur la couverture :","o":["Une image sobre peut être admise","Toujours une image décorative","Jamais d'image","Une photo personnelle"],"r":0,"e":"Travaux de recherche : image simple admise (silhouette, schéma). Articles/projets : pas d'image.","s":6},{"q":"Un bon titre est : (plusieurs)","o":["Simple","Précis","Attractif","Très long","Sensationnaliste"],"r":[0,1,2],"e":"Bon titre : simple, précis, attractif (sans sensationnalisme).","s":6},{"q":"Un titre scientifique idéal contient :","o":["La population, la condition et l'intervention ou la variable","Le seul nom de l'auteur principal","Le coût du matériel, et les noms de tous les auteurs du projet","Une citation célèbre, en exergue"],"r":0,"e":"Structure : Population + Condition + Intervention/Variable.","s":6},{"q":"Le résumé / abstract :","o":["Se rédige en premier, avant tout le reste","Se rédige en dernier, et doit être autonome","N'est jamais nécessaire dans un mémoire, sauf demande","Doit faire deux pages, au minimum"],"r":1,"e":"Le résumé se rédige en dernier, en 100-150 mots, et doit être compréhensible seul. Il compte 100 à 150 mots.","s":6},{"q":"Combien de mots-clés (keywords) en général ?","o":["1","3 à 6","10 à 15","Une vingtaine"],"r":1,"e":"3 à 6 keywords, spécifiques, alignés avec MeSH si possible.","s":6},{"q":"Une abréviation doit être :","o":["Jamais expliquée","Définie à la première apparition","Définie uniquement dans la conclusion","En italique"],"r":1,"e":"Règle : toute abréviation/sigle est définie la 1ʳᵉ fois qu'elle apparaît.","s":6},{"q":"L'index (sommaire) est :","o":["Obligatoire pour les articles courts","Obligatoire pour les mémoires et les thèses","Inutile, quel que soit le document","Réservé aux livres et aux ouvrages de référence publiés"],"r":1,"e":"Index obligatoire pour les mémoires/thèses, peu utilisé pour les articles.","s":6},{"q":"L'introduction d'un mémoire doit : (plusieurs)","o":["Situer le contexte","Présenter le problème","Justifier le choix","Formuler la question et objectifs","Donner les résultats détaillés"],"r":[0,1,2,3],"e":"L'introduction situe, présente, justifie, formule question/objectifs et annonce la structure (PAS les résultats).","s":6},{"q":"Quel est l'ordre recommandé de rédaction ?","o":["L'introduction d'abord, puis le reste dans l'ordre","La discussion d'abord, l'introduction à la fin","La conclusion en premier, seule","N'importe lequel, sans conséquence"],"r":1,"e":"Conseil : rédiger l'introduction après la discussion/conclusion pour assurer la cohérence.","s":6},{"q":"La revue de littérature n'est PAS :","o":["Une synthèse critique des travaux publiés","Une analyse organisée par thèmes","Un enchaînement de copier-coller","Un état de l'art du domaine"],"r":2,"e":"La revue n'est pas un copier-coller, c'est une analyse critique structurée.","s":6},{"q":"On organise la revue de littérature plutôt par :","o":["La date de publication des articles","Le nom des auteurs, par ordre alphabétique","Les thèmes, comme la douleur ou la fonction","Le pays d'origine des études"],"r":2,"e":"Par thèmes pour éviter l'effet « liste ».","s":6},{"q":"Dans la section RÉSULTATS, on doit :","o":["Interpréter les chiffres obtenus","Décrire les données telles qu'elles sont","Discuter les résultats avec ceux des autres études publiées","Conclure sur l'hypothèse de départ"],"r":1,"e":"Règle d'or : on DÉCRIT dans les résultats, on INTERPRÈTE dans la discussion.","s":6},{"q":"Chaque tableau/figure doit :","o":["Être posé sans être cité","Être mentionné dans le texte","Apparaître uniquement en annexe","Être imprimé en couleur"],"r":1,"e":"Chaque tableau ou figure doit être mentionné dans le texte (ex. « comme présenté dans le Tableau 4.12 »).","s":6},{"q":"La discussion comporte (en ordre type) :","o":["Résultat, comparaison, interprétation et limites","Méthodes, résultats, puis références","Citations, bibliographie et ordre alphabétique","Les limites seules, puis les perspectives de recherche"],"r":0,"e":"Structure type : résultat → comparaison → interprétation → limites → implications cliniques. Les implications cliniques viennent en dernier.","s":6},{"q":"Une bonne conclusion doit : (plusieurs)","o":["Répondre à la question de recherche","Reprendre les objectifs de l'étude","Mentionner les limites du travail","Affirmer des conclusions très fortes"],"r":[0,1,2],"e":"Conclusion : répond à la question, reprend objectifs, mentionne limites. Éviter les conclusions trop fortes.","s":6},{"q":"On préfère écrire :","o":["« Il est prouvé que… »","« Les résultats suggèrent que… »","« C'est toujours efficace »","« Ça marche bien, sans aucun doute »"],"r":1,"e":"« Les résultats suggèrent que… » est plus prudent, surtout pour un petit échantillon.","s":6},{"q":"Les APPENDICES sont :","o":["Du matériel créé ou adapté par les auteurs","Du matériel externe, non créé par eux","Toujours obligatoires dans un mémoire","Réservés aux thèses de doctorat, en sciences dures"],"r":0,"e":"Appendices = matériel créé par les auteurs (questionnaires construits, grilles…).","s":6},{"q":"Les ANNEXES sont :","o":["Du matériel créé par les auteurs eux-mêmes","Du matériel externe, comme le questionnaire original","Identiques aux appendices, sous un autre nom plus récent","Des documents sans titre ni numérotation"],"r":1,"e":"Annexes = matériel externe (version originale SF-36, brochures officielles, autorisations). Brochures officielles et autorisations en font partie, comme le SF-36 original.","s":6},{"q":"Un article scientifique a comme structure :","o":["Titre, résumé, introduction, méthodes, résultats, discussion","Couverture, page de garde et préface","Index, annexes, appendices, bibliographie, lexique et remerciements","Un cas clinique unique, commenté"],"r":0,"e":"Structure standard d'article (limité en mots). Puis la conclusion et les références.","s":6},{"q":"Une thèse est :","o":["Identique à un article, en plus long","Complète, originale, volumineuse et très rigoureuse","Sans annexes, pour limiter le volume, et sans appendices","Sans bibliographie, l'auteur étant expert"],"r":1,"e":"Thèse = structure complète + exigences supplémentaires (originalité, volume, rigueur).","s":6},{"q":"Quelles sources peuvent figurer en bibliographie ? (plusieurs)","o":["Articles scientifiques","Livres","Guidelines","Sites sérieux","Inventions"],"r":[0,1,2,3],"e":"Biblio : sources réellement utilisées (articles, livres, guidelines, sites sérieux).","s":6},{"q":"Règle d'or : ce qui est cité dans le texte…","o":["…peut être absent de la bibliographie","…doit apparaître dans la bibliographie","…ne va jamais en biblio","…n'est jamais répété"],"r":1,"e":"Tout ce qui est cité → dans la biblio, et inversement.","s":6},{"q":"Le résumé doit contenir : (plusieurs)","o":["Contexte","Objectifs","Éléments clés de la méthodologie","Résultats majeurs","Conclusion + implication clinique","Anecdotes personnelles"],"r":[0,1,2,3,4],"e":"Résumé : contexte + objectifs + méthodo + résultats + conclusion.","s":6},{"q":"Un abréviation est :","o":["Une suite d'initiales, comme WCPT, OMS ou EVA","Un mot abrégé, comme « máx. » ou « aprox. »","Un synonyme exact d'un acronyme","Un élément inutile du texte"],"r":1,"e":"Abréviation = mot abrégé. Acronyme = initiales (EVA, SF-36, WCPT).","s":6},{"q":"Quel critère pour la pagination ?","o":["Toutes les pages sont comptées, annexes comprises","Seules les pages du texte principal sont comptées","Aucune page n'est numérotée ni comptée","Les annexes, elles, ne sont pas comptées"],"r":0,"e":"Pagination continue, toutes les pages comptées (y compris annexes).","s":6},{"q":"Une page de garde est :","o":["Toujours obligatoire, quelle que soit l'institution","Facultative selon l'institution, juste après la couverture","Dépourvue de toute information","Identique à la couverture, avec la même image en couleur et le logo"],"r":1,"e":"Page de garde : facultative, sobre, reprend les infos de la couverture sans images. Elle est sobre, sans image.","s":6},{"q":"L'organisation d'un travail scientifique permet au lecteur :","o":["De suivre la logique et de juger la qualité du travail","D'apprécier l'esthétique de la mise en page du document","De gagner du temps de lecture, et rien de plus","De vérifier rapidement la bibliographie"],"r":0,"e":"Ce n'est donc pas un détail esthétique. Il trouve aussi facilement une information.","s":6},{"q":"Sur la couverture d'un travail de recherche, une petite image :","o":["Est admise, comme une silhouette ou un schéma articulaire","Est obligatoire, pour attirer le regard","Est interdite, quel que soit le travail","Doit être en couleur, et occuper au moins la moitié de la page"],"r":0,"e":"Pour un article, une monographie ou un projet, aucune image n'est admise.","s":6},{"q":"La structure idéale d'un titre est :","o":["La population, la condition et l'intervention","L'intervention, le résultat et la conclusion","Le nom de l'auteur, le sujet et l'année de publication","Le problème, la méthode et le résultat"],"r":0,"e":"Un bon titre est simple, précis et attractif. L'intervention peut être remplacée par une variable.","s":6},{"q":"Le résumé doit être rédigé :","o":["En dernier, et compréhensible seul","En premier, avant l'introduction","Juste après l'introduction, avant les méthodes du mémoire","Avant la méthodologie, pour guider"],"r":0,"e":"Il compte 100 à 150 mots et s'accompagne de mots-clés.","s":6},{"q":"Le résumé contient notamment :","o":["Contexte, objectifs, méthode, résultats majeurs et conclusion","La seule conclusion, avec ses implications","Les seuls résultats, présentés en détail avec tous les tableaux","La seule méthodologie, de façon détaillée"],"r":0,"e":"Sa longueur de 100 à 150 mots impose une grande concision. Le contexte tient en 2 ou 3 phrases et la conclusion inclut une implication clinique.","s":6},{"q":"Les mots-clés doivent être :","o":["De 3 à 6, spécifiques et précis","Au nombre de 10, au minimum","Génériques, comme « therapy »","En français uniquement, traduits du titre"],"r":0,"e":"Il faut éviter les termes trop généraux comme « therapy ». Ils s'alignent idéalement sur les termes MeSH.","s":6},{"q":"Un acronyme se distingue d'une abréviation en ce qu'il :","o":["Est formé d'initiales, comme l'OMS ou l'EVA","Est un mot abrégé, comme « max. »","Est toujours écrit en minuscules","N'a jamais besoin d'être défini, comme l'IRM"],"r":0,"e":"Toute abréviation ou sigle doit être défini à sa première occurrence dans le texte.","s":6},{"q":"L'index ou sommaire est :","o":["Exigé pour mémoires et thèses, pas pour les articles","Obligatoire dans tous les documents, même courts","Facultatif dans tous les documents","Interdit dans les thèses de doctorat"],"r":0,"e":"Le cours recommande d'utiliser les styles Word pour sa génération automatique.","s":6},{"q":"L'introduction doit notamment :","o":["Situer le contexte, poser le problème et formuler la question","Présenter les résultats principaux","Discuter les limites de l'étude","Résumer toute la littérature, article par article, en détail"],"r":0,"e":"Le cours conseille de la rédiger après la discussion et la conclusion, pour la cohérence. Elle justifie aussi le sujet, présente les objectifs, esquisse la méthodologie et annonce la structure.","s":6},{"q":"La revue de littérature s'organise :","o":["Par thèmes, comme la douleur ou la fonction","Étude par étude, dans l'ordre de lecture","Par ordre chronologique des publications","Par auteur, selon l'ordre alphabétique des noms de famille"],"r":0,"e":"C'est une synthèse organisée et critique, pas un enchaînement de copier-coller. On évite de procéder étude par étude.","s":6},{"q":"La règle d'or de la section Résultats est :","o":["On décrit, sans commenter","On interprète, en détail","On compare, avec les autres études publiées","On conclut, sur l'hypothèse"],"r":0,"e":"L'interprétation appartient à la Discussion ; chaque tableau ou figure doit être mentionné dans le texte.","s":6},{"q":"La structure type de la discussion est :","o":["Résultat, comparaison, interprétation, limites et implication","Limites, résultats, puis conclusion et perspectives","Interprétation, puis résultats bruts et limites","Conclusion, puis comparaison aux autres études publiées"],"r":0,"e":"Elle donne du sens aux résultats décrits précédemment.","s":6},{"q":"La conclusion doit :","o":["Répondre à la question, synthétiser et ouvrir des pistes","Présenter de nouveaux résultats, non décrits avant","Discuter la méthodologie en détail, pas à pas","Citer de nouvelles références récentes"],"r":0,"e":"Il faut préférer « les résultats suggèrent que » à « il est prouvé que ». Elle reprend les objectifs et mentionne les limites.","s":6},{"q":"La méthodologie doit détailler :","o":["Variables, population, outils, procédures et éthique","Les seuls instruments de mesure, sans le reste","La seule population étudiée et son âge","Les seules procédures suivies au cours de l'étude"],"r":0,"e":"C'est ce qui permet la reproductibilité de l'étude. Question, objectifs, hypothèses et traitement des données en font aussi partie.","s":6},{"q":"Les appendices contiennent :","o":["Du matériel créé ou adapté, comme un questionnaire construit","Du matériel externe, comme le SF-36 original","La bibliographie complète du travail","Le résumé du mémoire, en français et en anglais, avec mots-clés"],"r":0,"e":"Les annexes contiennent le matériel non créé par les auteurs, comme la version originale du SF-36. Les grilles d'observation en font partie.","s":6},{"q":"Chaque appendice ou annexe doit comporter :","o":["Une page-titre, un numéro romain et un renvoi dans le texte","Un résumé de son contenu en début de page","Une bibliographie propre, en fin d'annexe","Une pagination séparée, différente de celle du reste du document"],"r":0,"e":"Cette rigueur formelle permet au lecteur de s'y retrouver.","s":6},{"q":"La règle d'or de la bibliographie est :","o":["Tout ce qui est cité y figure, et inversement","Citer le plus de références possible","Ne citer que les articles récents, de moins de cinq ans","Citer uniquement les revues indexées"],"r":0,"e":"Elle suit une norme définie, APA ou Vancouver. Elle suit une norme définie.","s":6},{"q":"L'article scientifique se caractérise par :","o":["Un format court et standardisé, avec une limite de mots","Une structure complète, comme celle d'un mémoire","L'absence de résumé en début d'article","L'absence de références, remplacées par des notes de bas de page"],"r":0,"e":"Il suit la séquence titre, abstract, introduction, méthodes, résultats, discussion, conclusion et références.","s":6},{"q":"La thèse se distingue par :","o":["Une structure complète, originale et très rigoureuse","Un format court, limité en mots comme un article de revue","L'absence d'annexes et d'appendices","Une seule étude, obligatoirement"],"r":0,"e":"Le document de recherche, typique des mémoires, a une structure complète mais un volume moindre. Elle est volumineuse et comporte souvent plusieurs études.","s":6},{"q":"La couverture doit être :","o":["Formelle, sobre et lisible, avec toutes les mentions","Illustrée, avec une grande photo en pleine page","En couleur, pour attirer l'attention du jury","Manuscrite, pour la personnaliser davantage"],"r":0,"e":"Un logo peut parfois y figurer. Titre complet, nom, institution, cursus, année, lieu, date et nom de l'orienteur.","s":6},{"q":"La rédaction scientifique demande : (plusieurs)","o":["La clarté du propos","La cohérence des idées","Une structure logique","Le respect des normes","Un style fleuri et personnel"],"r":[0,1,2,3],"e":"Clarté + cohérence + structure + normes + rigueur intellectuelle.","s":7},{"q":"Les 4 qualités d'un bon style scientifique sont :","o":["Objectivité, clarté, cohérence logique et rigueur","Émotion, humour, créativité et grande originalité","Brièveté, slogan, persuasion et style","Citations, listes, métaphores et images"],"r":0,"e":"4 qualités : objectivité, clarté, cohérence logique, rigueur scientifique.","s":7},{"q":"Quel interligne pour le texte principal ?","o":["1","1,5","2","3"],"r":1,"e":"Interligne 1,5 pour le texte principal · simple pour les notes/légendes/références.","s":7},{"q":"Quelles marges standard ?","o":["1 cm partout, pour gagner de la place sur chaque page","2,5 cm en haut, en bas et à gauche, 2 cm à droite","5 cm partout, pour les annotations","Aucune règle, selon l'imprimante"],"r":1,"e":"Marges standard universitaires : 2,5 cm sauf 2 cm à droite.","s":7},{"q":"Quelle police est recommandée ?","o":["Comic Sans MS ou Calibri, en taille 14","Times New Roman ou Arial, en taille 12","Papyrus ou Garamond, en taille 11","Wingdings ou Symbol, en taille 10"],"r":1,"e":"Times New Roman ou Arial, taille 12 pour le texte courant.","s":7},{"q":"Quel niveau hiérarchique est CENTRÉ ET EN MAJUSCULES ?","o":["Niveau 1","Niveau 3","Niveau 5","Aucun"],"r":0,"e":"Niveau 1 : CENTRÉ + MAJUSCULES (grands titres).","s":7},{"q":"Les nombres en rédaction : 1 à 9 sont :","o":["En chiffres","En toutes lettres","Au choix","En italique"],"r":1,"e":"1 à 9 en lettres, 10+ en chiffres. EXCEPTION : les résultats toujours en chiffres.","s":7},{"q":"Pour les résultats (% et n), on utilise :","o":["Toujours des chiffres","Toujours des lettres","Du chinois","Du romain"],"r":0,"e":"Dans les résultats : toujours des chiffres (7,2 %, n = 34).","s":7},{"q":"On évite en rédaction scientifique : (plusieurs)","o":["Les points d'exclamation","Les adjectifs intensifs, comme « très »","Les formules comme « je trouve que »","Les références bibliographiques"],"r":[0,1,2],"e":"Éviter : points d'exclamation, intensifs, opinions personnelles (« je trouve que »).","s":7},{"q":"Toute affirmation doit être :","o":["Personnelle, fondée sur son ressenti","Justifiée par un raisonnement, un exemple ou une référence","Romantique, pour toucher le lecteur","Laissée sans source, si elle semble évidente au lecteur averti"],"r":1,"e":"Affirmation = raisonnement / exemple / référence.","s":7},{"q":"Une PARAPHRASE est :","o":["Une citation mot à mot, entre guillemets","Une reformulation fidèle, avec ses propres mots","Une copie du texte sans citer l'auteur","Un plagiat, même si la source est indiquée en fin de texte"],"r":1,"e":"Paraphrase = reformulation fidèle, référence toujours requise, sans guillemets. La référence reste obligatoire.","s":7},{"q":"Quelle est la forme préférée en rédaction scientifique ?","o":["La transcription longue","La paraphrase","La copie","Aucune"],"r":1,"e":"La paraphrase est privilégiée car elle montre la compréhension.","s":7},{"q":"Une transcription courte se fait à partir de :","o":["≥ 40 mots","< 40 mots","Toujours","Jamais"],"r":1,"e":"Transcription courte (< 40 mots) : entre guillemets, intégrée au paragraphe.","s":7},{"q":"Une transcription longue (≥ 40 mots) :","o":["Reste entre guillemets dans le paragraphe","Se met en bloc indenté, sans guillemets","Est interdite dans un mémoire","N'a pas besoin de référence, puisqu'elle est longue et visible"],"r":1,"e":"Citation longue : bloc indenté, sans guillemets, avec auteur+année+page. C'est la règle de l'APA ; on indique auteur, année et page.","s":7},{"q":"En APA 7, dans le texte : (Auteur, année) est le format pour :","o":["Les citations","Les abréviations","Les marges","Les en-têtes"],"r":0,"e":"Format APA 7 : (Auteur, année) dans le texte.","s":7},{"q":"En APA 7, avec 3 auteurs ou plus, on écrit :","o":["Tous les auteurs à chaque fois","et al. dès la 1ʳᵉ citation","et al. uniquement après 10 citations","Pas de mention"],"r":1,"e":"APA 7 : et al. dès la 1ʳᵉ citation pour 3+ auteurs.","s":7},{"q":"Combien d'auteurs maximum dans la bibliographie APA 7 ?","o":["3","6","Jusqu'à 20","Aucune limite"],"r":2,"e":"APA 7 : jusqu'à 20 auteurs listés dans la bibliographie.","s":7},{"q":"En APA 7, le DOI est écrit :","o":["Sous la forme d'un lien complet, en https","Sans aucun préfixe, après le titre","Entre crochets, après la date de consultation","Il n'est pas écrit du tout"],"r":0,"e":"APA 7 : DOI = lien complet https://doi.org/… Le lien commence par https://doi.org/.","s":7},{"q":"En APA 7, le lieu d'édition (ville) :","o":["Il reste toujours obligatoire","Il n'est plus requis pour les livres","Il doit être écrit en italique","Il s'écrit en anglais uniquement"],"r":1,"e":"APA 7 : le lieu d'édition n'est plus requis pour les livres.","s":7},{"q":"En APA, plusieurs auteurs dans la même parenthèse sont classés :","o":["Par ordre alphabétique","Par ordre chronologique","Par âge","Sans ordre"],"r":0,"e":"(Gomes, 2001 ; Lages, 1991 ; Silva, 2010) — ordre alphabétique.","s":7},{"q":"« e.g. » signifie :","o":["c'est-à-dire","par exemple","et caetera","versus"],"r":1,"e":"e.g. = par exemple. i.e. = c'est-à-dire. etc. = et caetera. vs. = versus.","s":7},{"q":"« i.e. » signifie :","o":["Par exemple, en latin","C'est-à-dire, en latin id est","Et cetera, pour clore une liste","Et les autres, en latin et alii"],"r":1,"e":"i.e. = id est = c'est-à-dire.","s":7},{"q":"« vs. » signifie :","o":["par exemple","versus","et al.","page"],"r":1,"e":"vs. = versus.","s":7},{"q":"En APA, plusieurs œuvres d'un même auteur la même année :","o":["Un suffixe a, b ou c après l'année","La mention « bis » après l'année","Un numéro romain, placé avant le nom de l'auteur","Un symbole dièse après la date"],"r":0,"e":"Suffixes : (Auteur, 2018a), (Auteur, 2018b). Par exemple 2018a et 2018b.","s":7},{"q":"Quels sont les éléments minimums d'une référence APA ? (plusieurs)","o":["Auteur","Année","Titre","Source (éditeur, revue, DOI…)","Photo de l'auteur"],"r":[0,1,2,3],"e":"Référence APA : auteur(s), année, titre, source (éditeur ou revue+vol+pages+DOI).","s":7},{"q":"Une bonne revue critique de bibliographie :","o":["Empile des références, sans aucune analyse ni lien","Repère accords, controverses et lacunes","Recopie les résumés, sans les relire","Liste les sources, sans aucun contexte"],"r":1,"e":"Une révision critique présente l'état des connaissances, identifie accords/controverses/lacunes.","s":7},{"q":"Pour relire son texte : (plusieurs)","o":["Le lendemain (distance)","À voix haute","Par un tiers","Sans modifier"],"r":[0,1,2],"e":"Relire à distance, à voix haute, par un tiers, avec dictionnaire/correcteur.","s":7},{"q":"Les connecteurs « cependant », « néanmoins », « en revanche » servent à :","o":["Ajouter","Opposer","Conclure","Illustrer"],"r":1,"e":"Connecteurs d'opposition : cependant, néanmoins, en revanche.","s":7},{"q":"Le plagiat est :","o":["Accepté s'il est rare","Grave dans le monde académique","Encouragé pour gagner du temps","Indifférent pour le jury"],"r":1,"e":"Le plagiat est grave : il faut citer correctement et préférer la paraphrase.","s":7},{"q":"Vrai ou faux : la forme (mise en page) ne compte pas, seul le contenu importe.","o":["Vrai","Faux"],"r":1,"e":"Faux : un texte mal formaté donne une impression de manque de rigueur.","s":7},{"q":"Savoir rédiger est présenté comme :","o":["Une compétence scientifique, et pas seulement linguistique","Une compétence purement linguistique","Un talent inné, que l'on possède ou non dès l'enfance, sans travail","Une simple formalité administrative"],"r":0,"e":"On y juge ce que l'étudiant a compris et sa capacité à l'exprimer.","s":7},{"q":"Les cinq qualités requises en rédaction scientifique sont :","o":["Clarté, cohérence, structure, normes et rigueur intellectuelle","Clarté, brièveté, style, normes et originalité","Objectivité, clarté, cohérence et rigueur","Structure, normes, style, émotion, persuasion et grande originalité"],"r":0,"e":"La rigueur intellectuelle exclut le copier-coller et la pseudo-science.","s":7},{"q":"Les quatre volets du chapitre sur la rédaction sont :","o":["Mise en forme, style, citations et références bibliographiques","Titre, résumé, corps et bibliographie","Introduction, méthodes, résultats et discussion, avec la conclusion","Clarté, cohérence, structure et normes"],"r":0,"e":"Ils couvrent la forme comme le fond.","s":7},{"q":"Le niveau 5 de la hiérarchie des titres se présente :","o":["En alinéa, en minuscules et en italique, avec un point","Centré, en majuscules et en gras, sans point final","Centré, avec majuscules et italique, sans alinéa","Aligné à gauche, en gras, avec un point final"],"r":0,"e":"Le niveau 1 est centré et en majuscules, le niveau 4 aligné à gauche en majuscules et italique. L'alinéa est de 5 espaces.","s":7},{"q":"Concernant la pagination, la couverture :","o":["Est comptée, mais sans numéro affiché","N'est pas comptée du tout","Porte le numéro 1, affiché","Est numérotée en chiffres romains"],"r":0,"e":"Toutes les pages sont comptées, y compris bibliographie et annexes.","s":7},{"q":"L'interligne des notes de bas de page, légendes et références est :","o":["Simple","De 1,5","Double","De 2"],"r":0,"e":"Le texte principal est, lui, en interligne 1,5.","s":7},{"q":"Les marges standard sont :","o":["2,5 cm en haut, en bas et à gauche, 2 cm à droite","2 cm en haut et en bas, 3 cm à gauche comme à droite","3 cm partout, sur les quatre côtés","2,5 cm partout, sans exception"],"r":0,"e":"Il faut choisir soit l'alinéa en début de paragraphe, soit l'espace entre paragraphes, mais pas les deux.","s":7},{"q":"La taille de police recommandée pour les légendes et notes est :","o":["10","12","14","8"],"r":0,"e":"Le texte courant est en 12 et les titres en 14 à 16, voire 18.","s":7},{"q":"L'italique s'emploie pour :","o":["Les mots étrangers et les noms de journaux","Les titres de chapitres et de sections du texte","Les mots-clés importants","Les citations courtes"],"r":0,"e":"Le gras sert aux titres et mots-clés importants ; le souligné est de plus en plus évité. Les termes techniques aussi.","s":7},{"q":"L'objectivité en rédaction scientifique exclut :","o":["Les formules comme « je trouve que »","Les références bibliographiques, dans le texte","Les exemples cliniques concrets et chiffrés","Les connecteurs logiques entre les phrases"],"r":0,"e":"La clarté impose par ailleurs des phrases courtes et un vocabulaire précis, en évitant « ça marche bien ». « À mon avis » est aussi à proscrire.","s":7},{"q":"La cohérence logique suppose une progression :","o":["Idée, explication, exemple","Exemple, idée, explication","Conclusion, idée, exemple","Explication, exemple, idée"],"r":0,"e":"La rigueur scientifique exige, elle, précision des termes, données correctes et absence de contradictions.","s":7},{"q":"Les connecteurs « ainsi », « en résumé » et « par conséquent » servent à :","o":["Conclure","Ajouter","Opposer","Illustrer"],"r":0,"e":"« Cependant », « néanmoins » et « en revanche » servent à opposer ; « par exemple » et « notamment » à illustrer.","s":7},{"q":"Les adjectifs intensifs comme « très » ou « extrêmement » :","o":["Affaiblissent le sérieux et doivent être limités","Renforcent l'argument scientifique du texte","Sont recommandés dans la discussion finale","Sont neutres, sans aucun effet"],"r":0,"e":"Les points d'exclamation sont également à éviter.","s":7},{"q":"Concernant les nombres, la règle est :","o":["De 1 à 9 en lettres, au-delà en chiffres, résultats en chiffres","Tout en chiffres, sans exception","Tout en lettres, sans exception","De 1 à 20 en lettres, au-delà en chiffres, et résultats en lettres"],"r":0,"e":"Les résultats comme 7,2 % ou n=34 s'écrivent donc toujours en chiffres.","s":7},{"q":"Parmi les conseils de relecture, le cours cite :","o":["Relire à distance, à voix haute et par un tiers","La seule relecture immédiate, juste après","Le seul correcteur automatique du logiciel","La seule relecture par un tiers, sans soi"],"r":0,"e":"La relecture à voix haute teste notamment la fluidité. Dictionnaire et correcteur complètent la relecture.","s":7},{"q":"La paraphrase est décrite comme :","o":["La forme préférée en science, qui reconstruit l'idée fidèlement","Un simple changement de quelques mots du texte original de l'auteur","Une citation recopiée sans guillemets","Un résumé du texte original, plus court"],"r":0,"e":"La transcription mot à mot est à utiliser avec modération, entre guillemets.","s":7},{"q":"Une transcription longue, d'au moins 40 mots :","o":["Se met en bloc indenté, sans guillemets","Se met entre guillemets, dans le texte","S'intègre au paragraphe, comme une citation courte","Ne nécessite aucune référence"],"r":0,"e":"La transcription courte, de moins de 40 mots, s'intègre au paragraphe entre guillemets. En APA, on indique auteur, année et page.","s":7},{"q":"La citation « Valentim et Chaves (2006) ont montré… » correspond à la forme :","o":["Auteur sujet","Parenthèses en fin de phrase","Accent sur l'année","Citation longue"],"r":0,"e":"Les trois formes possibles sont auteur sujet, parenthèses finales et accent sur l'année.","s":7},{"q":"En APA 7, à partir de trois auteurs, on écrit :","o":["« et al. » dès la première citation","Tous les auteurs la première fois","Les deux premiers auteurs","« et coll. » à partir de la deuxième citation"],"r":0,"e":"Pour un ou deux auteurs, on cite les noms, comme (Gil & Neves, 2000).","s":7},{"q":"En APA 7, dans une transcription courte, la référence prend la forme :","o":["(auteur, année, p. xx)","(auteur, année)","(auteur, titre, éditeur, année)","(année, p. xx)"],"r":0,"e":"La page est indispensable dès lors qu'il y a reproduction exacte du texte.","s":7}]};
